const FA_CODEUI_HTML = "<!doctype html>\n<html lang=\"zh-Hant\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>__TITLE__</title>\n<style>\n:root{--bg:#fff;--fg:#1f2328;--mut:#656d76;--bd:#d0d7de;--ac:#0969da;--sf:#f6f8fa;--hl:#fff8c5;--ok:#1a7f37;--er:#cf222e}\n@media (prefers-color-scheme:dark){:root{--bg:#0d1117;--fg:#e6edf3;--mut:#8b949e;--bd:#30363d;--ac:#58a6ff;--sf:#161b22;--hl:#3b2e00;--ok:#3fb950;--er:#f85149}}\n*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.6 -apple-system,\"Segoe UI\",\"Noto Sans TC\",sans-serif;display:flex;flex-direction:column}\nheader{display:flex;align-items:center;gap:12px;padding:8px 14px;border-bottom:1px solid var(--bd);background:var(--sf);flex-wrap:wrap}\nheader h1{font-size:16px;margin:0;word-break:break-all}header .st{color:var(--mut);font-size:12px}\nnav{display:flex;gap:4px;margin-left:auto}nav button{padding:5px 12px;border:1px solid var(--bd);background:var(--bg);color:var(--fg);border-radius:6px;cursor:pointer;font-size:13px}\nnav button.on{border-color:var(--ac);color:var(--ac);font-weight:600}\n#load{padding:30px;text-align:center;color:var(--mut)}#bar{height:6px;background:var(--bd);border-radius:3px;margin:10px auto;max-width:420px;overflow:hidden}#bar i{display:block;height:100%;width:0;background:var(--ac)}\n#app{flex:1;display:flex;min-height:0}\n.pane{display:none;flex:1;min-height:0}.pane.on{display:flex}\n.side{width:330px;max-width:42vw;border-right:1px solid var(--bd);display:flex;flex-direction:column;background:var(--sf);min-height:0}\n.side input,.side select{margin:8px 10px 0;padding:7px 9px;border:1px solid var(--bd);border-radius:6px;background:var(--bg);color:var(--fg);font-size:13px}\n.list{flex:1;overflow:auto;padding:8px 6px 14px}\n.list a,.list summary{display:block;padding:3px 8px;border-radius:5px;color:var(--fg);text-decoration:none;cursor:pointer;word-break:break-all}\n.list a:hover,.list summary:hover{background:var(--bd)}.list .k{color:var(--mut);font-size:12px;margin-left:6px}.list details>div{margin-left:12px}\n.main{flex:1;overflow:auto;padding:16px 26px 70px;min-width:0}\nh1.t{font-size:20px;margin:0 0 8px;word-break:break-all}h1,h2,h3{line-height:1.3}h2{font-size:16px;margin:20px 0 6px;border-bottom:1px solid var(--bd);padding-bottom:4px}h3{font-size:14px;margin:14px 0 4px}\n.mut{color:var(--mut)}code,pre,textarea{font-family:ui-monospace,Consolas,monospace;font-size:12.5px}pre{background:var(--sf);border:1px solid var(--bd);border-radius:6px;padding:8px 10px;overflow:auto;margin:6px 0}\n:not(pre)>code{background:var(--sf);border:1px solid var(--bd);border-radius:4px;padding:0 4px}\na.l,.md a{color:var(--ac);cursor:pointer;text-decoration:none}a.l:hover,.md a:hover{text-decoration:underline}\ntable{border-collapse:collapse;width:100%;margin:6px 0}td,th{border-bottom:1px solid var(--bd);padding:4px 8px;text-align:left;vertical-align:top;word-break:break-word}th{background:var(--sf);position:sticky;top:0}\n.tag{display:inline-block;padding:0 7px;border-radius:10px;background:var(--sf);border:1px solid var(--bd);font-size:12px;color:var(--mut);margin-right:4px}\n.note{background:var(--hl);border-radius:6px;padding:6px 10px;margin:8px 0}.err{color:var(--er);white-space:pre-wrap}\n.md ul,.md ol{padding-left:22px}.md blockquote{border-left:3px solid var(--bd);margin:6px 0;padding:0 10px;color:var(--mut)}\nsvg.dg{max-width:100%;height:auto;background:var(--sf);border:1px solid var(--bd);border-radius:6px;margin:6px 0}svg.dg text{fill:var(--fg);font:12px sans-serif}svg.dg rect{fill:var(--bg);stroke:var(--ac)}svg.dg path{stroke:var(--mut);fill:none}\n.ask{display:flex;gap:8px}.ask input{flex:1;padding:9px 11px;border:1px solid var(--bd);border-radius:6px;background:var(--bg);color:var(--fg);font-size:14px}\nbutton.b{padding:7px 14px;border:1px solid var(--ac);background:var(--ac);color:#fff;border-radius:6px;cursor:pointer}button.b.s{background:var(--bg);color:var(--ac)}\n.chips{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}.chips span{padding:2px 9px;border:1px solid var(--bd);border-radius:12px;cursor:pointer;font-size:12px;color:var(--mut)}.chips span:hover{border-color:var(--ac);color:var(--ac)}\n.qa{border:1px solid var(--bd);border-radius:8px;padding:10px 14px;margin:12px 0}.qa .q{font-weight:600;margin-bottom:4px}\ntextarea{width:100%;min-height:110px;padding:8px;border:1px solid var(--bd);border-radius:6px;background:var(--bg);color:var(--fg);resize:vertical}\n.res{overflow:auto;max-height:60vh;border:1px solid var(--bd);border-radius:6px;margin-top:8px}\n@media (max-width:720px){.pane.on{flex-direction:column}.side{width:100%;max-width:none;height:40vh}.main{padding:12px}}\n</style></head><body>\n<header><h1 id=\"ttl\"></h1><span class=\"st\" id=\"stat\"></span><nav id=\"nav\"></nav></header>\n<div id=\"load\"><div id=\"lmsg\">載入中…</div><div id=\"bar\"><i id=\"barfill\"></i></div></div>\n<div id=\"app\" style=\"display:none\">\n<section class=\"pane\" id=\"p-wiki\"><div class=\"side\"><input id=\"wq\" placeholder=\"搜尋頁面…\"><div class=\"list\" id=\"wl\"></div></div><div class=\"main\" id=\"wm\"></div></section>\n<section class=\"pane\" id=\"p-files\"><div class=\"side\"><input id=\"fq\" placeholder=\"搜尋檔案路徑…\"><div class=\"list\" id=\"fl\"></div></div><div class=\"main\" id=\"fm\"></div></section>\n<section class=\"pane\" id=\"p-syms\"><div class=\"side\"><input id=\"sq\" placeholder=\"搜尋函式／類別名稱或說明…\"><select id=\"sk\"><option value=\"\">所有種類</option></select><div class=\"list\" id=\"sl\"></div></div><div class=\"main\" id=\"sm\"></div></section>\n<section class=\"pane\" id=\"p-ask\"><div class=\"main\" id=\"am\" style=\"max-width:980px\">\n<h1 class=\"t\">問答（離線，不需要網路或AI）</h1>\n<div class=\"mut\">像 doxygen＋語意搜尋：依索引裡的定義、註解、依賴與呼叫關係回答。中英文都可以，函式名稱請照原樣寫。</div>\n<div class=\"ask\" style=\"margin-top:10px\"><input id=\"aq\" placeholder=\"例如：parse_config 是做什麼的？／main 在哪裡定義？／誰用到 Logger？／登入流程相關的檔案\" autofocus><button class=\"b\" id=\"ago\">問</button></div>\n<div class=\"chips\" id=\"achips\"></div><div id=\"aout\"></div></div></section>\n<section class=\"pane\" id=\"p-sql\"><div class=\"main\" id=\"qm\" style=\"max-width:1100px\">\n<h1 class=\"t\">SQL 查詢（內嵌 SQLite）</h1>\n<div class=\"mut\">資料表：files、symbols、imports（src→dst，檔案之間的引用）、uses（file_id 呼叫了 symbol_id）、pages、glossary、meta；檢視：v_symbols、v_imports、v_uses。id 是序號（從0開始）。Ctrl+Enter 執行。</div>\n<div style=\"margin:8px 0\"><select id=\"qex\"></select></div>\n<textarea id=\"qsql\" spellcheck=\"false\"></textarea>\n<div style=\"margin:8px 0;display:flex;gap:8px;align-items:center\"><button class=\"b\" id=\"qrun\">執行</button><button class=\"b s\" id=\"qcsv\">下載CSV</button><span class=\"mut\" id=\"qinfo\"></span></div>\n<div class=\"res\" id=\"qres\"></div>\n<details style=\"margin-top:12px\"><summary class=\"mut\">資料表結構</summary><pre id=\"qschema\"></pre></details></div></section>\n</div>\n<script id=\"cfg\" type=\"application/json\">__CFG__</script>\n<script id=\"payload\" type=\"application/json\">__PAYLOAD__</script>\n<script>\n__RUNTIME__\n</script>\n<script>\n(function(){\nvar CFG=JSON.parse(document.getElementById('cfg').textContent);\nvar DB=null,IX=null,SQLDB=null,PAGES=[],GLOSS={},fileMap={},LASTCOLS=[],LASTROWS=[];\nfunction $(s){return document.querySelector(s)}\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]})}\nfunction b64u8(b){var bin=atob(b),n=bin.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);return u}\nasync function gunzip(u8,gz){if(!gz)return u8;var r=new Response(new Blob([u8]).stream().pipeThrough(new DecompressionStream('gzip')));return new Uint8Array(await r.arrayBuffer())}\nfunction setLoad(msg,pct){$('#lmsg').textContent=msg;if(pct!=null)$('#barfill').style.width=Math.round(pct)+'%'}\nfunction tick(){return new Promise(function(r){setTimeout(r,0)})}\nfunction loadScript(text){return new Promise(function(res,rej){var u=URL.createObjectURL(new Blob([text],{type:'application/javascript'}));var s=document.createElement('script');s.src=u;s.onload=function(){URL.revokeObjectURL(u);res()};s.onerror=function(){rej(new Error('載入SQLite引擎失敗'))};document.head.appendChild(s)})}\nfunction rows(sql){var r=SQLDB.exec(sql);return r.length?r[0].values:[]}\nfunction F(i){return DB.files[i]||['?','',0,'']}\nfunction S(i){return DB.syms[i]}\nfunction link(path,label){return '<a class=\"l\" data-go=\"file:'+esc(path)+'\">'+esc(label||path)+'</a>'}\nfunction slink(name){return '<a class=\"l\" data-go=\"sym:'+esc(name)+'\">'+esc(name)+'</a>'}\n/* ---- 迷你Markdown ---- */\nfunction inline(t){\n  t=esc(t);\n  t=t.replace(/`([^`]+)`/g,function(m,c){var p=c.replace(/:\\d+(-\\d+)?$/,'');return fileMap[p]!=null?'<a class=\"l\" data-go=\"file:'+esc(p)+'\"><code>'+c+'</code></a>':(IX&&IX.nameMap[c.toLowerCase()]?'<a class=\"l\" data-go=\"sym:'+esc(c)+'\"><code>'+c+'</code></a>':'<code>'+c+'</code>')});\n  t=t.replace(/\\*\\*([^*]+)\\*\\*/g,'<b>$1</b>').replace(/\\[([^\\]]+)\\]\\(page:([^)]+)\\)/g,'<a class=\"l\" data-go=\"page:$2\">$1</a>').replace(/\\[([^\\]]+)\\]\\((https?:[^)]+)\\)/g,'<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>');\n  return t;\n}\nfunction mdToHtml(md){\n  var lines=String(md||'').split('\\n'),h='',i=0;\n  while(i<lines.length){\n    var l=lines[i];\n    if(/^```/.test(l)){var lang=l.replace(/^```/,'').trim();var buf=[];i++;while(i<lines.length&&!/^```/.test(lines[i])){buf.push(lines[i]);i++}i++;\n      if(lang==='mermaid'){var sv=mermaidLite(buf.join('\\n'));h+=sv||'<pre>'+esc(buf.join('\\n'))+'</pre>'}else h+='<pre>'+esc(buf.join('\\n'))+'</pre>';continue}\n    var m;\n    if((m=/^(#{1,4})\\s+(.*)$/.exec(l))){var n=m[1].length;h+='<h'+n+'>'+inline(m[2])+'</h'+n+'>';i++;continue}\n    if(/^\\|.*\\|\\s*$/.test(l)&&i+1<lines.length&&/^\\|[\\s:|-]+\\|\\s*$/.test(lines[i+1])){var hd=l.split('|').slice(1,-1);i+=2;var rows=[];while(i<lines.length&&/^\\|.*\\|\\s*$/.test(lines[i])){rows.push(lines[i].split('|').slice(1,-1));i++}\n      h+='<table><tr>'+hd.map(function(c){return '<th>'+inline(c.trim())+'</th>'}).join('')+'</tr>'+rows.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+inline(c.trim())+'</td>'}).join('')+'</tr>'}).join('')+'</table>';continue}\n    if(/^\\s*[-*]\\s+/.test(l)){var it=[];while(i<lines.length&&/^\\s*[-*]\\s+/.test(lines[i])){it.push('<li>'+inline(lines[i].replace(/^\\s*[-*]\\s+/,''))+'</li>');i++}h+='<ul>'+it.join('')+'</ul>';continue}\n    if(/^\\s*\\d+\\.\\s+/.test(l)){var it2=[];while(i<lines.length&&/^\\s*\\d+\\.\\s+/.test(lines[i])){it2.push('<li>'+inline(lines[i].replace(/^\\s*\\d+\\.\\s+/,''))+'</li>');i++}h+='<ol>'+it2.join('')+'</ol>';continue}\n    if(/^>\\s?/.test(l)){var q=[];while(i<lines.length&&/^>\\s?/.test(lines[i])){q.push(lines[i].replace(/^>\\s?/,''));i++}h+='<blockquote>'+inline(q.join(' '))+'</blockquote>';continue}\n    if(!l.trim()){i++;continue}\n    var p=[l];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,4}\\s|```|\\s*[-*]\\s|\\s*\\d+\\.\\s|>|\\|)/.test(lines[i])){p.push(lines[i]);i++}\n    h+='<p>'+inline(p.join(' '))+'</p>';\n  }\n  return h;\n}\n/* ---- 迷你流程圖（只支援 graph LR/TD 的節點與箭頭）---- */\nfunction mermaidLite(src){\n  var ls=src.split('\\n').map(function(x){return x.trim()}).filter(Boolean);\n  if(!ls.length||!/^(graph|flowchart)\\s+(LR|RL|TD|TB|BT)/i.test(ls[0]))return '';\n  var dir=/LR|RL/i.test(ls[0])?'LR':'TD';var nodes={},order=[],edges=[];\n  function nd(tok){var m=/^([A-Za-z0-9_\\-.]+)\\s*(?:\\[\\[?\"?([^\\]\"]*)\"?\\]?\\]|\\(\\(?\"?([^)\"]*)\"?\\)?\\)|\\{\"?([^}\"]*)\"?\\})?$/.exec(tok.trim());if(!m)return null;var id=m[1];var label=m[2]||m[3]||m[4];if(!nodes[id]){nodes[id]={id:id,label:label||id};order.push(id)}else if(label)nodes[id].label=label;return id}\n  for(var k=1;k<ls.length;k++){var ln=ls[k];if(/^(subgraph|end|classDef|class|style|linkStyle|%%)/.test(ln))continue;\n    var parts=ln.split(/\\s*(?:-->|---|-\\.->|==>)\\s*(?:\\|([^|]*)\\|\\s*)?/);\n    var ids=[];for(var j=0;j<parts.length;j+=2){var id=nd(parts[j]||'');if(!id)return '';ids.push({id:id,lab:parts[j+1]||''})}\n    for(var e=0;e+1<ids.length;e++)edges.push({a:ids[e].id,b:ids[e+1].id,lab:ids[e+1].lab||''});}\n  if(!order.length||order.length>60)return '';\n  var rank={};order.forEach(function(id){rank[id]=0});\n  for(var it=0;it<order.length;it++){var ch=false;edges.forEach(function(e){if(e.a!==e.b&&rank[e.b]<rank[e.a]+1&&rank[e.a]+1<order.length){rank[e.b]=rank[e.a]+1;ch=true}});if(!ch)break}\n  var cols={};order.forEach(function(id){(cols[rank[id]]=cols[rank[id]]||[]).push(id)});\n  var W=170,H=44,GX=60,GY=22,pos={},maxc=0,maxr=0;\n  Object.keys(cols).forEach(function(r){cols[r].forEach(function(id,idx){pos[id]=dir==='LR'?{x:r*(W+GX)+10,y:idx*(H+GY)+10}:{x:idx*(W+GX)+10,y:r*(H+GY+20)+10};maxc=Math.max(maxc,pos[id].x+W+10);maxr=Math.max(maxr,pos[id].y+H+10)})});\n  var s='<svg class=\"dg\" viewBox=\"0 0 '+maxc+' '+maxr+'\" width=\"'+Math.min(maxc,900)+'\"><defs><marker id=\"ar\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--mut);stroke:none\"/></marker></defs>';\n  edges.forEach(function(e){var a=pos[e.a],b=pos[e.b];if(!a||!b)return;var x1=dir==='LR'?a.x+W:a.x+W/2,y1=dir==='LR'?a.y+H/2:a.y+H,x2=dir==='LR'?b.x:b.x+W/2,y2=dir==='LR'?b.y+H/2:b.y;var mx=(x1+x2)/2,my=(y1+y2)/2;\n    s+='<path d=\"M'+x1+','+y1+' C'+(dir==='LR'?mx:x1)+','+(dir==='LR'?y1:my)+' '+(dir==='LR'?mx:x2)+','+(dir==='LR'?y2:my)+' '+x2+','+y2+'\" marker-end=\"url(#ar)\"/>';if(e.lab)s+='<text x=\"'+mx+'\" y=\"'+(my-3)+'\" text-anchor=\"middle\">'+esc(e.lab)+'</text>'});\n  order.forEach(function(id){var p=pos[id],lb=nodes[id].label;if(lb.length>24)lb=lb.slice(0,23)+'…';s+='<rect x=\"'+p.x+'\" y=\"'+p.y+'\" width=\"'+W+'\" height=\"'+H+'\" rx=\"6\"/><text x=\"'+(p.x+W/2)+'\" y=\"'+(p.y+H/2+4)+'\" text-anchor=\"middle\">'+esc(lb)+'</text>'});\n  return s+'</svg>';\n}\n\nasync function boot(){\n  $('#ttl').textContent=CFG.title;\n  var P=JSON.parse(document.getElementById('payload').textContent);\n  if(CFG.mode==='sqlite'){\n    setLoad('解壓縮 SQLite 引擎…',3);\n    var js=new TextDecoder().decode(await gunzip(b64u8(P.js),CFG.sql.gz.js));\n    var wasm=await gunzip(b64u8(P.wasm),CFG.sql.gz.wasm);\n    await loadScript(js);\n    setLoad('載入資料庫…',10);\n    var dbBytes=await gunzip(b64u8(P.db),CFG.sql.gz.db);\n    var SQL=await initSqlJs({wasmBinary:wasm.buffer.slice(wasm.byteOffset,wasm.byteOffset+wasm.byteLength)});\n    SQLDB=new SQL.Database(dbBytes);\n    setLoad('讀取資料表…',18);await tick();\n    DB={root:CFG.root,files:rows('SELECT path,lang,lines,doc,note FROM files ORDER BY id'),syms:rows('SELECT name,kind,file_id,line,doc,sig,note FROM symbols ORDER BY id'),imps:rows('SELECT src,dst FROM imports'),uses:rows('SELECT file_id,symbol_id FROM uses')};\n    PAGES=rows('SELECT id,title,kind,auto,md FROM pages').map(function(r){return {id:r[0],title:r[1],kind:r[2],auto:!!r[3],md:r[4]}});\n    rows('SELECT term,definition FROM glossary').forEach(function(r){GLOSS[r[0]]={definition:r[1]}});\n  }else{\n    setLoad('解壓縮資料…',5);\n    var j=JSON.parse(new TextDecoder().decode(await gunzip(b64u8(P.data),CFG.dataGz)));\n    DB=j;PAGES=j.pages||[];GLOSS=j.glossary||{};\n  }\n  DB.files.forEach(function(f,i){fileMap[f[0]]=i});\n  setLoad('建立檢索索引…',22);await tick();\n  IX=_faCodeIndexNew(DB);\n  var total=(DB.syms.length+DB.files.length)||1;\n  while(!_faCodeIndexTokens(IX,120)){setLoad('建立檢索索引… '+Math.round((IX.ti+IX.tf)/total*100)+'%',22+78*(IX.ti+IX.tf)/total);await tick()}\n  $('#load').style.display='none';$('#app').style.display='flex';\n  $('#stat').textContent=CFG.stats.files+' 個檔案 · '+CFG.stats.symbols+' 個定義 · '+CFG.stats.imports+' 條引用 · '+CFG.stats.uses+' 條呼叫'+(CFG.complete?'':' · （部分索引）')+' · 產生於 '+new Date(CFG.generated).toLocaleString();\n  var tabs=[['wiki','百科'],['files','檔案'],['syms','符號'],['ask','問答']];if(SQLDB)tabs.push(['sql','SQL']);\n  $('#nav').innerHTML=tabs.map(function(t){return '<button data-t=\"'+t[0]+'\">'+t[1]+'</button>'}).join('');\n  $('#nav').onclick=function(e){var b=e.target.closest('button');if(b)show(b.dataset.t)};\n  initWiki();initFiles();initSyms();initAsk();if(SQLDB)initSql();\n  show(PAGES.length?'wiki':'ask');\n}\nfunction show(t){document.querySelectorAll('.pane').forEach(function(p){p.classList.toggle('on',p.id==='p-'+t)});document.querySelectorAll('#nav button').forEach(function(b){b.classList.toggle('on',b.dataset.t===t)});if(t==='ask')$('#aq').focus()}\nfunction go(g){var i=g.indexOf(':'),k=g.slice(0,i),v=g.slice(i+1);\n  if(k==='file'){show('files');showFile(v)}else if(k==='sym'){show('syms');showSym(v)}else if(k==='page'){show('wiki');showPage(v)}}\ndocument.addEventListener('click',function(e){var a=e.target.closest('[data-go]');if(a){e.preventDefault();go(a.dataset.go)}});\n/* ---- 百科 ---- */\nfunction initWiki(){\n  function render(){var q=$('#wq').value.trim().toLowerCase();var h='';\n    PAGES.forEach(function(p){if(q&&p.title.toLowerCase().indexOf(q)<0&&String(p.md).toLowerCase().indexOf(q)<0)return;h+='<a data-go=\"page:'+esc(p.id)+'\">'+esc(p.title)+(p.auto?'<span class=\"k\">草稿</span>':'')+'</a>'});\n    var gl=Object.keys(GLOSS);if(gl.length&&!q)h+='<div class=\"mut\" style=\"padding:8px 8px 2px\">名詞</div>'+gl.sort().map(function(t){return '<a data-go=\"term:'+esc(t)+'\">'+esc(t)+'</a>'}).join('');\n    $('#wl').innerHTML=h||'<div class=\"mut\" style=\"padding:8px\">沒有符合的頁面</div>'}\n  $('#wq').oninput=render;render();\n  if(PAGES.length)showPage(PAGES[0].id);else{var h2='<h1 class=\"t\">專案概況</h1><div class=\"mut\">'+esc(CFG.root)+'</div><p>這份匯出沒有百科頁面，請用「檔案」「符號」「問答」。</p>';$('#wm').innerHTML=h2}\n}\nfunction showPage(id){var p=PAGES.filter(function(x){return x.id===id})[0];if(!p){$('#wm').innerHTML='<div class=\"note\">沒有這個頁面</div>';return}\n  $('#wm').innerHTML='<div class=\"md\">'+(p.auto?'<div class=\"note\">這一頁是依程式碼結構自動產生的草稿。</div>':'')+mdToHtml(p.md)+'</div>';$('#wm').scrollTop=0}\n/* ---- 檔案 ---- */\nfunction initFiles(){\n  var tree={};DB.files.forEach(function(f,i){var segs=f[0].split('/'),n=tree;for(var k=0;k<segs.length-1;k++){n=(n.d=n.d||{})[segs[k]]=(n.d&&n.d[segs[k]])||{}}(n.f=n.f||[]).push(i)});\n  function node(n,depth){var h='';Object.keys(n.d||{}).sort().forEach(function(k){h+='<details'+(depth<1?' open':'')+'><summary>'+esc(k)+'/</summary><div>'+node(n.d[k],depth+1)+'</div></details>'});\n    (n.f||[]).slice(0,300).forEach(function(i){h+='<a data-go=\"file:'+esc(F(i)[0])+'\">'+esc(F(i)[0].split('/').pop())+'<span class=\"k\">'+(IX.fileSyms[i]||[]).length+'</span></a>'});return h}\n  var lazy=null;\n  function render(){var q=$('#fq').value.trim().toLowerCase();\n    if(!q){if(!lazy)lazy=node(tree,0);$('#fl').innerHTML=lazy;return}\n    var h='',c=0;for(var i=0;i<DB.files.length&&c<200;i++){if(DB.files[i][0].toLowerCase().indexOf(q)>=0){c++;h+='<a data-go=\"file:'+esc(DB.files[i][0])+'\">'+esc(DB.files[i][0])+'</a>'}}\n    $('#fl').innerHTML=h||'<div class=\"mut\" style=\"padding:8px\">沒有符合的檔案</div>'}\n  $('#fq').oninput=render;render();\n  $('#fm').innerHTML='<h1 class=\"t\">檔案</h1><div class=\"mut\">左邊選一個檔案，看它定義了什麼、引用了誰、被誰引用。</div>';\n}\nfunction showFile(path){var i=fileMap[path];if(i==null){$('#fm').innerHTML='<div class=\"note\">索引裡沒有這個檔案</div>';return}\n  var f=F(i),syms=IX.fileSyms[i]||[],out=IX.impOut[i]||[],inn=IX.impIn[i]||[],uses=IX.fileUses[i]||[];\n  var h='<h1 class=\"t\">'+esc(path)+'</h1><div><span class=\"tag\">'+esc(f[1])+'</span><span class=\"tag\">'+f[2]+' 行</span></div>';\n  if(f[4])h+='<div class=\"note\"><b>說明（AI 讀過程式碼後補充）</b>：'+esc(f[4])+'</div>';\n  if(f[3])h+='<p>'+esc(f[3])+'</p>';\n  h+='<h2>定義（'+syms.length+'）</h2>';\n  if(syms.length){h+='<table>';syms.slice(0,400).forEach(function(k){var s=S(k);h+='<tr><td>'+slink(s[0])+'</td><td><span class=\"tag\">'+esc(s[1])+'</span></td><td>第 '+s[3]+' 行</td><td>'+(s[4]?esc(s[4])+'<br>':'')+(s[5]?'<code>'+esc(s[5])+'</code>':'')+'</td></tr>'});h+='</table>'}else h+='<div class=\"mut\">（沒有抽到定義）</div>';\n  h+='<h2>引用了誰（'+out.length+'）</h2>'+(out.length?out.slice(0,200).map(function(k){return '<div>'+link(F(k)[0])+'</div>'}).join(''):'<div class=\"mut\">（沒有內部引用）</div>');\n  h+='<h2>被誰引用（'+inn.length+'）</h2>'+(inn.length?inn.slice(0,200).map(function(k){return '<div>'+link(F(k)[0])+'</div>'}).join(''):'<div class=\"mut\">（沒有已分析的檔案引用它）</div>');\n  if(uses.length){var seen={};h+='<h2>呼叫了別處的定義（'+uses.length+'）</h2>'+uses.slice(0,200).filter(function(k){return !seen[k]&&(seen[k]=1)}).map(function(k){var s=S(k);return '<div>'+slink(s[0])+' <span class=\"mut\">'+esc(F(s[2])[0])+':'+s[3]+'</span></div>'}).join('')}\n  $('#fm').innerHTML=h;$('#fm').scrollTop=0}\n/* ---- 符號 ---- */\nfunction initSyms(){\n  var kinds={};DB.syms.forEach(function(s){kinds[s[1]]=(kinds[s[1]]||0)+1});\n  $('#sk').innerHTML='<option value=\"\">所有種類</option>'+Object.keys(kinds).sort(function(a,b){return kinds[b]-kinds[a]}).map(function(k){return '<option value=\"'+esc(k)+'\">'+esc(k)+'（'+kinds[k]+'）</option>'}).join('');\n  var order=null;\n  function render(){var q=$('#sq').value.trim().toLowerCase(),kd=$('#sk').value,h='',c=0;\n    if(!order){order=DB.syms.map(function(s,i){return i}).sort(function(a,b){return String(DB.syms[a][0]).toLowerCase()<String(DB.syms[b][0]).toLowerCase()?-1:1})}\n    for(var n=0;n<order.length&&c<300;n++){var s=DB.syms[order[n]];if(kd&&s[1]!==kd)continue;if(q&&String(s[0]).toLowerCase().indexOf(q)<0&&String(s[4]).toLowerCase().indexOf(q)<0)continue;c++;h+='<a data-go=\"sym:'+esc(s[0])+'\">'+esc(s[0])+'<span class=\"k\">'+esc(s[1])+' · '+esc(F(s[2])[0].split('/').pop())+'</span></a>'}\n    $('#sl').innerHTML=h||'<div class=\"mut\" style=\"padding:8px\">沒有符合的結果</div>'+(c>=300?'':'')}\n  $('#sq').oninput=render;$('#sk').onchange=render;render();\n  $('#sm').innerHTML='<h1 class=\"t\">符號</h1><div class=\"mut\">函式、類別、結構、巨集…（最多列300筆，用上面的搜尋縮小範圍）。</div>';\n}\nfunction showSym(name){var ids=IX.nameMap[String(name).toLowerCase()]||[];\n  if(!ids.length){$('#sm').innerHTML='<div class=\"note\">索引裡沒有「'+esc(name)+'」</div>';return}\n  var h='<h1 class=\"t\">'+esc(S(ids[0])[0])+'</h1><div class=\"mut\">'+ids.length+' 個定義</div>';\n  ids.slice(0,12).forEach(function(k){var s=S(k),fi=s[2];\n    h+='<h2>'+esc(s[1])+'　'+link(F(fi)[0],F(fi)[0]+':'+s[3])+'</h2>';\n    h+=s[6]?'<div class=\"note\"><b>說明（AI 讀過程式碼後補充）</b>：'+esc(s[6])+'</div>':'';\n    h+=s[4]?'<p>'+esc(s[4])+'</p>':(s[6]?'':'<p class=\"mut\">'+esc(_faCodeNameGuess(s[0]))+'</p>');\n    if(s[5])h+='<pre>'+esc(s[5])+'</pre>';\n    var users=(IX.usedBy[k]||[]);if(users.length)h+='<div><b>被這些檔案呼叫／使用（'+users.length+'）：</b> '+users.slice(0,30).map(function(u){return link(F(u)[0])}).join('、')+'</div>';\n    var inn=IX.impIn[fi]||[];if(inn.length)h+='<div class=\"mut\" style=\"margin-top:4px\">定義它的檔案被 '+inn.length+' 個檔案引用：'+inn.slice(0,12).map(function(u){return link(F(u)[0])}).join('、')+'</div>';\n    var same=(IX.fileSyms[fi]||[]).filter(function(x){return x!==k}).slice(0,15);if(same.length)h+='<div style=\"margin-top:4px\"><b>同檔案的其他定義：</b> '+same.map(function(x){return slink(S(x)[0])}).join('、')+'</div>'});\n  $('#sm').innerHTML=h;$('#sm').scrollTop=0}\n/* ---- 問答 ---- */\nfunction initAsk(){\n  var ex=['這個專案是做什麼的','哪些檔案被最多檔案引用','處理設定檔的函式在哪','錯誤處理相關的程式'];\n  var big=DB.syms.length?DB.syms[0][0]:'main';\n  ex=[big+' 是做什麼的','where is '+big+' defined','誰用到 '+big,big+' 相關的東西'].concat(ex.slice(2));\n  $('#achips').innerHTML=ex.map(function(x){return '<span>'+esc(x)+'</span>'}).join('');\n  $('#achips').onclick=function(e){if(e.target.tagName==='SPAN'){$('#aq').value=e.target.textContent;ask()}};\n  $('#ago').onclick=ask;$('#aq').onkeydown=function(e){if(e.key==='Enter')ask()};\n}\nfunction ask(){var q=$('#aq').value.trim();if(!q)return;var t0=performance.now();var r=_faCodeAsk(IX,q);\n  var ms=Math.round(performance.now()-t0);\n  var h='<div class=\"qa\"><div class=\"q\">'+esc(q)+'</div><div class=\"md\">'+mdToHtml(r.answer)+'</div><div class=\"mut\" style=\"margin-top:6px\">意圖：'+esc({where:'找定義位置',who:'誰在用',related:'相關',deps:'檔案依賴',purpose:'做什麼用',about:'關於',search:'語意搜尋'}[r.intent]||r.intent)+' · '+ms+' ms</div></div>';\n  $('#aout').insertAdjacentHTML('afterbegin',h);$('#aq').select()}\n/* ---- SQL ---- */\nvar EXAMPLES=[\n['被最多檔案引用的檔案（Top 30）',\"SELECT path, imported_by_n AS 被引用數, imports_n AS 引用數 FROM files ORDER BY imported_by_n DESC LIMIT 30\"],\n['某檔案引用了誰／被誰引用（改 LIKE 裡的檔名）',\"SELECT 'imports' AS 方向, dst_path AS 檔案 FROM v_imports WHERE src_path LIKE '__FILE__'\\nUNION ALL\\nSELECT 'imported_by', src_path FROM v_imports WHERE dst_path LIKE '__FILE__'\"],\n['某檔案的所有間接依賴（遞迴）',\"WITH RECURSIVE dep(id, depth) AS (\\n  SELECT id, 0 FROM (SELECT id FROM files WHERE path LIKE '__FILE__' ORDER BY id LIMIT 1)\\n  UNION\\n  SELECT i.dst, dep.depth + 1 FROM imports i JOIN dep ON i.src = dep.id WHERE dep.depth < 6\\n)\\nSELECT f.path, MIN(dep.depth) AS 距離 FROM dep JOIN files f ON f.id = dep.id GROUP BY f.path ORDER BY 距離, f.path\"],\n['最常被呼叫的函式（依呼叫它的檔案數）',\"SELECT symbol AS 名稱, defined_in AS 定義在, COUNT(DISTINCT caller_file) AS 呼叫的檔案數 FROM v_uses GROUP BY symbol, defined_in ORDER BY 呼叫的檔案數 DESC LIMIT 30\"],\n['某個符號的所有使用者（改名稱）',\"SELECT DISTINCT caller_file AS 使用的檔案, defined_in AS 定義在 FROM v_uses WHERE symbol = '__SYM__'\"],\n['同名定義（可能衝突或多型）',\"SELECT name, COUNT(*) AS 個數, group_concat(path, '  |  ') AS 位置 FROM v_symbols GROUP BY name HAVING COUNT(*) > 1 ORDER BY 個數 DESC LIMIT 50\"],\n['定義最多的檔案',\"SELECT f.path, COUNT(*) AS 定義數 FROM symbols s JOIN files f ON f.id = s.file_id GROUP BY f.id ORDER BY 定義數 DESC LIMIT 30\"],\n['孤立檔案（沒人引用、也沒引用別人）',\"SELECT path, lines FROM files WHERE imports_n = 0 AND imported_by_n = 0 ORDER BY lines DESC LIMIT 100\"],\n['說明（註解）裡有某個關鍵字的定義',\"SELECT name, kind, path, line, doc FROM v_symbols WHERE doc LIKE '%config%' ORDER BY name LIMIT 50\"],\n['AI 補過說明的定義（note 欄位）',\"SELECT name, kind, path, line, note FROM v_symbols WHERE note IS NOT NULL AND note <> '' ORDER BY path, line LIMIT 100\"],\n['各目錄的檔案數與行數',\"SELECT dir AS 目錄, COUNT(*) AS 檔案數, SUM(lines) AS 總行數 FROM files GROUP BY dir ORDER BY 總行數 DESC LIMIT 40\"],\n['各語言統計',\"SELECT lang AS 語言, COUNT(*) AS 檔案數, SUM(lines) AS 行數 FROM files GROUP BY lang ORDER BY 行數 DESC\"]\n];\nfunction initSql(){\n  var hot='%',sym='main';\n  try{var a=SQLDB.exec('SELECT name FROM files ORDER BY imports_n+imported_by_n DESC LIMIT 1');if(a.length)hot='%'+a[0].values[0][0]+'%';var b=SQLDB.exec('SELECT symbol FROM v_uses GROUP BY symbol ORDER BY COUNT(*) DESC LIMIT 1');if(b.length)sym=b[0].values[0][0]}catch(e){}\n  EXAMPLES.forEach(function(x){x[1]=x[1].split('__FILE__').join(hot).split('__SYM__').join(sym)});\n  $('#qex').innerHTML='<option value=\"\">範例查詢…</option>'+EXAMPLES.map(function(x,i){return '<option value=\"'+i+'\">'+esc(x[0])+'</option>'}).join('');\n  $('#qex').onchange=function(){if(this.value!=='')$('#qsql').value=EXAMPLES[this.value][1]};\n  $('#qsql').value=EXAMPLES[0][1];\n  $('#qrun').onclick=runSql;$('#qsql').onkeydown=function(e){if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();runSql()}};\n  $('#qcsv').onclick=function(){if(!LASTCOLS.length)return;var csv=[LASTCOLS].concat(LASTROWS).map(function(r){return r.map(function(c){c=c==null?'':String(c);return /[\",\\n]/.test(c)?'\"'+c.replace(/\"/g,'\"\"')+'\"':c}).join(',')}).join('\\n');var a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv'}));a.download='query.csv';a.click()};\n  try{var sc=SQLDB.exec(\"SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' ORDER BY type DESC,name\");$('#qschema').textContent=sc.length?sc[0].values.map(function(r){return r[1]+';'}).join('\\n\\n'):''}catch(e){}\n}\nfunction runSql(){var sql=$('#qsql').value.trim();if(!sql)return;var t0=performance.now();\n  try{var res=SQLDB.exec(sql);var ms=Math.round(performance.now()-t0);\n    if(!res.length){$('#qres').innerHTML='<div style=\"padding:10px\" class=\"mut\">執行完成，沒有回傳資料列。</div>';$('#qinfo').textContent=ms+' ms';LASTCOLS=[];LASTROWS=[];return}\n    var r=res[res.length-1];LASTCOLS=r.columns;LASTROWS=r.values;var max=500;\n    var h='<table><tr>'+r.columns.map(function(c){return '<th>'+esc(c)+'</th>'}).join('')+'</tr>'+r.values.slice(0,max).map(function(row){return '<tr>'+row.map(function(c,ci){var t=c==null?'':String(c);var col=r.columns[ci];var lk=(/path|file|defined_in|檔案|定義在|src_path|dst_path|caller/i.test(col)&&fileMap[t]!=null)?link(t):esc(t);return '<td>'+lk+'</td>'}).join('')+'</tr>'}).join('')+'</table>';\n    $('#qres').innerHTML=h;$('#qinfo').textContent=r.values.length+' 列'+(r.values.length>max?'（畫面只顯示前'+max+'列，CSV是完整的）':'')+' · '+ms+' ms'}\n  catch(e){$('#qres').innerHTML='<div style=\"padding:10px\" class=\"err\">'+esc(e.message||e)+'</div>';$('#qinfo').textContent=''}}\nboot().catch(function(e){$('#lmsg').innerHTML='<span class=\"err\">載入失敗：'+esc(e&&e.message||e)+'</span>'});\n})();\n</script>\n</body></html>\n";
/* CODEUI-END */
/* PYBRIDGE-BEGIN */
const FA_PYBRIDGE_FILES = {"anthropic/__init__.py":"# -*- coding: utf-8 -*-\n\"\"\"\nanthropic（Claude）的「轉接版」：Floating AI Assistant 在執行技能包的 Python 腳本時提供。\n\n腳本照原本的寫法（同步或 async）：\n    from anthropic import Anthropic, AsyncAnthropic\n    client = Anthropic(api_key=...)\n    msg = client.messages.create(model=\"claude-...\", max_tokens=1024, system=\"...\", messages=[...], tools=[...])\n    print(msg.content[0].text)\n    with client.messages.stream(...) as s:\n        for t in s.text_stream: ...\n\n實際上不會連 Anthropic，而是把 Claude 格式的請求轉成 chat/completions，交給助理「已設定的 LLM Model 清單」裡的 Model\n（有 tools 就挑支援工具呼叫的、有圖片就挑支援讀圖的；腳本自己的 api_key、model 都忽略），再把回應轉回 Claude 的格式\n（content 區塊、stop_reason、usage、tool_use、串流事件）。所有 Model 都不支援該功能才丟 anthropic.NotSupportedError。\n\"\"\"\nimport json\nimport re\n\nimport fa_bridge\nimport fa_llm\n\n__version__ = \"0.99.0+fa-bridge\"\n\n\n# ---------------------------------------------------------------- 錯誤\nclass AnthropicError(Exception):\n    pass\n\n\nclass APIError(AnthropicError):\n    def __init__(self, message=\"\", request=None, body=None, **kw):\n        super(APIError, self).__init__(message)\n        self.message = message\n        self.request = request\n        self.body = body\n\n\nclass APIStatusError(APIError):\n    status_code = 500\n\n    def __init__(self, message=\"\", response=None, body=None, status_code=None, **kw):\n        super(APIStatusError, self).__init__(message, body=body)\n        self.response = response\n        if status_code:\n            self.status_code = status_code\n\n\nclass APIConnectionError(APIError):\n    pass\n\n\nclass APITimeoutError(APIConnectionError):\n    pass\n\n\nclass BadRequestError(APIStatusError):\n    status_code = 400\n\n\nclass AuthenticationError(APIStatusError):\n    status_code = 401\n\n\nclass PermissionDeniedError(APIStatusError):\n    status_code = 403\n\n\nclass NotFoundError(APIStatusError):\n    status_code = 404\n\n\nclass RateLimitError(APIStatusError):\n    status_code = 429\n\n\nclass InternalServerError(APIStatusError):\n    status_code = 500\n\n\nclass NotSupportedError(APIStatusError, NotImplementedError):\n    status_code = 501\n\n\n_CLS = {400: BadRequestError, 401: AuthenticationError, 403: PermissionDeniedError, 404: NotFoundError, 429: RateLimitError}\n\n\ndef _translate(e):\n    if isinstance(e, fa_bridge.NotSupported):\n        return NotSupportedError(str(e) or \"沒有任何已設定的 LLM Model 支援這個功能\")\n    msg = str(e)\n    m = re.search(r\"API錯誤\\((\\d{3})\\)\", msg)\n    if m:\n        c = int(m.group(1))\n        return (_CLS.get(c) or (InternalServerError if c >= 500 else APIStatusError))(msg, status_code=c)\n    if \"逾時\" in msg:\n        return APITimeoutError(msg)\n    return APIConnectionError(msg)\n\n\n# ---------------------------------------------------------------- 物件\nclass _Obj(object):\n    def __init__(self, d):\n        self.__dict__[\"_d\"] = d\n\n    def __getattr__(self, k):\n        if k.startswith(\"__\"):\n            raise AttributeError(k)\n        return _wrap(self.__dict__[\"_d\"].get(k))\n\n    def __getitem__(self, k):\n        return _wrap(self.__dict__[\"_d\"][k])\n\n    def get(self, k, default=None):\n        return _wrap(self.__dict__[\"_d\"].get(k, default))\n\n    def to_dict(self, **kw):\n        return self.__dict__[\"_d\"]\n\n    model_dump = to_dict\n\n    def to_json(self, **kw):\n        return json.dumps(self.__dict__[\"_d\"], ensure_ascii=False)\n\n    model_dump_json = to_json\n\n    def __repr__(self):\n        return \"<anthropic.%s %r>\" % (self.__dict__[\"_d\"].get(\"type\", \"obj\"), self.__dict__[\"_d\"])\n\n\ndef _wrap(v):\n    if isinstance(v, dict):\n        return _Obj(v)\n    if isinstance(v, list):\n        return [_wrap(x) for x in v]\n    return v\n\n\ndef _message(resp, model):\n    return fa_llm.chat_to_anthropic(resp, model)\n\n\n# ---------------------------------------------------------------- 串流管理員：messages.stream(...)\nclass MessageStream(object):\n    def __init__(self, msg):\n        self._m = msg\n        self._events = list(fa_llm.anthropic_events(msg))\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        return False\n\n    def __iter__(self):\n        for e in self._events:\n            yield _Obj(e)\n\n    @property\n    def text_stream(self):\n        for e in self._events:\n            if e.get(\"type\") == \"content_block_delta\" and e[\"delta\"].get(\"type\") == \"text_delta\":\n                yield e[\"delta\"][\"text\"]\n\n    def get_final_message(self):\n        return _Obj(self._m)\n\n    def get_final_text(self):\n        return \"\".join(b.get(\"text\", \"\") for b in self._m[\"content\"] if b[\"type\"] == \"text\")\n\n    def until_done(self):\n        return None\n\n\nclass AsyncMessageStream(object):\n    def __init__(self, awaitable_msg):\n        self._aw = awaitable_msg\n        self._m = None\n        self._events = []\n\n    async def __aenter__(self):\n        self._m = await self._aw\n        self._events = list(fa_llm.anthropic_events(self._m))\n        return self\n\n    async def __aexit__(self, *a):\n        return False\n\n    def __aiter__(self):\n        async def gen():\n            for e in self._events:\n                yield _Obj(e)\n        return gen()\n\n    @property\n    def text_stream(self):\n        async def gen():\n            for e in self._events:\n                if e.get(\"type\") == \"content_block_delta\" and e[\"delta\"].get(\"type\") == \"text_delta\":\n                    yield e[\"delta\"][\"text\"]\n        return gen()\n\n    async def get_final_message(self):\n        return _Obj(self._m)\n\n    async def get_final_text(self):\n        return \"\".join(b.get(\"text\", \"\") for b in self._m[\"content\"] if b[\"type\"] == \"text\")\n\n\nclass Stream(object):\n    def __init__(self, events):\n        self._it = iter(events)\n\n    def __iter__(self):\n        return self\n\n    def __next__(self):\n        return _Obj(next(self._it))\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        return False\n\n\nclass AsyncStream(object):\n    def __init__(self, events):\n        self._it = iter(events)\n\n    def __aiter__(self):\n        return self\n\n    async def __anext__(self):\n        try:\n            return _Obj(next(self._it))\n        except StopIteration:\n            raise StopAsyncIteration\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *a):\n        return False\n\n\n# ---------------------------------------------------------------- 資源\ndef _build(A):\n    def prep(kw):\n        model = kw.get(\"model\")\n        stream = kw.get(\"stream\", False)\n        req = fa_llm.anthropic_to_chat(**{k: v for k, v in kw.items() if k != \"stream\"})\n        return model, stream, req\n\n    class Messages(object):\n        if A:\n            async def create(self, **kw):\n                model, stream, req = prep(kw)\n                try:\n                    r = await fa_llm.acomplete(req)\n                except Exception as e:\n                    raise _translate(e)\n                m = _message(r, model)\n                return AsyncStream(fa_llm.anthropic_events(m)) if stream else _Obj(m)\n\n            def stream(self, **kw):\n                model, _, req = prep(kw)\n\n                async def go():\n                    try:\n                        r = await fa_llm.acomplete(req)\n                    except Exception as e:\n                        raise _translate(e)\n                    return _message(r, model)\n                return AsyncMessageStream(go())\n\n            async def count_tokens(self, **kw):\n                return _Obj({\"input_tokens\": fa_llm.estimate_tokens({\"s\": kw.get(\"system\"), \"m\": kw.get(\"messages\")})})\n        else:\n            def create(self, **kw):\n                model, stream, req = prep(kw)\n                try:\n                    r = fa_llm.complete(req)\n                except Exception as e:\n                    raise _translate(e)\n                m = _message(r, model)\n                return Stream(fa_llm.anthropic_events(m)) if stream else _Obj(m)\n\n            def stream(self, **kw):\n                model, _, req = prep(kw)\n                try:\n                    r = fa_llm.complete(req)\n                except Exception as e:\n                    raise _translate(e)\n                return MessageStream(_message(r, model))\n\n            def count_tokens(self, **kw):\n                return _Obj({\"input_tokens\": fa_llm.estimate_tokens({\"s\": kw.get(\"system\"), \"m\": kw.get(\"messages\")})})\n\n        def __getattr__(self, k):\n            raise NotSupportedError(\"messages.%s 在 AI 助理的 anthropic 轉接版沒有支援\" % k)\n\n    class Completions(object):\n        \"\"\"舊的 text completions（prompt 以 \\\\n\\\\nHuman: … \\\\n\\\\nAssistant: 組成）。\"\"\"\n        if A:\n            async def create(self, model=None, prompt=\"\", max_tokens_to_sample=1024, **kw):\n                msgs = _legacy_prompt(prompt)\n                r = await fa_llm.acomplete(fa_llm.chat_request(model, msgs, max_tokens=max_tokens_to_sample, temperature=kw.get(\"temperature\")))\n                return _Obj({\"id\": \"compl_fa\", \"type\": \"completion\", \"model\": model, \"completion\": fa_llm.text_of(r[\"choices\"][0][\"message\"][\"content\"]), \"stop_reason\": \"stop_sequence\"})\n        else:\n            def create(self, model=None, prompt=\"\", max_tokens_to_sample=1024, **kw):\n                msgs = _legacy_prompt(prompt)\n                r = fa_llm.complete(fa_llm.chat_request(model, msgs, max_tokens=max_tokens_to_sample, temperature=kw.get(\"temperature\")))\n                return _Obj({\"id\": \"compl_fa\", \"type\": \"completion\", \"model\": model, \"completion\": fa_llm.text_of(r[\"choices\"][0][\"message\"][\"content\"]), \"stop_reason\": \"stop_sequence\"})\n\n    class Models(object):\n        def _info(self):\n            try:\n                return fa_bridge.call(\"llm.info\", {}, timeout=10.0).get(\"model\") or \"assistant\"\n            except Exception:\n                return \"assistant\"\n\n        if A:\n            async def list(self, **kw):\n                return _Obj({\"data\": [{\"id\": self._info(), \"type\": \"model\", \"display_name\": self._info()}], \"has_more\": False})\n        else:\n            def list(self, **kw):\n                return _Obj({\"data\": [{\"id\": self._info(), \"type\": \"model\", \"display_name\": self._info()}], \"has_more\": False})\n\n    class Client(object):\n        def __init__(self, api_key=None, base_url=None, auth_token=None, timeout=None, max_retries=None, default_headers=None, http_client=None, **kw):\n            self.api_key = api_key\n            self.base_url = base_url\n            self.messages = Messages()\n            self.completions = Completions()\n            self.models = Models()\n            self.beta = self\n\n        def with_options(self, **kw):\n            return self\n\n        copy = with_options\n\n        def close(self):\n            return None\n\n        def __getattr__(self, k):\n            if k.startswith(\"__\"):\n                raise AttributeError(k)\n            raise NotSupportedError(\"client.%s 在 AI 助理的 anthropic 轉接版沒有支援\" % k)\n    return Client\n\n\ndef _legacy_prompt(prompt):\n    msgs = []\n    parts = re.split(r\"\\n\\n(Human|Assistant):\", \"\\n\\n\" + str(prompt or \"\"))\n    i = 1\n    while i + 1 < len(parts):\n        role = \"user\" if parts[i] == \"Human\" else \"assistant\"\n        txt = parts[i + 1].strip()\n        if txt:\n            msgs.append({\"role\": role, \"content\": txt})\n        i += 2\n    return msgs or [{\"role\": \"user\", \"content\": str(prompt or \"\")}]\n\n\nclass Anthropic(_build(False)):\n    pass\n\n\nclass AsyncAnthropic(_build(True)):\n    async def close(self):\n        return None\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *a):\n        return False\n\n\nHUMAN_PROMPT = \"\\n\\nHuman:\"\nAI_PROMPT = \"\\n\\nAssistant:\"\n","fa_bridge.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_bridge — Python 端的「API 轉接」通道（由 Floating AI Assistant 在執行技能包的 Python 腳本時自動提供）。\n\n腳本裡呼叫的某些公開 API（例如 playwright.sync_api）在這個環境裡其實是轉接到 AI 助理自己的工具／領域，\n所以腳本不需要真的有 Chrome 遠端除錯埠、也不需要裝 Playwright。\n\n通訊方式：桌面版用檔案當信箱；網頁版（Pyodide）直接呼叫助理頁面的 JS 模組。桌面版的信箱做法：——把請求寫成 req-<id>.json 放進 FA_BRIDGE_RPC 資料夾，助理（主程式）處理後寫出 res-<id>.json。\n不需要開任何網路埠、不需要改主程式。\n\n直接用法：\n    import fa_bridge\n    fa_bridge.tool(\"browser_get_page_text\", tab_id=3)           # 呼叫助理的一個工具\n    fa_bridge.domain(\"browser_control\", \"開啟 https://… 並截圖\")  # 委派給助理的一個領域（子 AI）\n\"\"\"\nimport json\nimport os\nimport sys\nimport time\nimport uuid\n\nRPC_DIR = os.environ.get(\"FA_BRIDGE_RPC\", \"\")\nIN_BROWSER = sys.platform == \"emscripten\"  # 網頁版／Pyodide：直接呼叫助理頁面的 JS 模組 _fa_pybridge，不需要信箱檔案\n\n\nACTIVE = True  # 網頁版：停用轉接（一般的 python_execute）時設成 False，攔截會全部放行\n\n\nclass BridgeError(RuntimeError):\n    pass\n\n\nclass NotSupported(BridgeError):\n    \"\"\"助理設定的所有 LLM Model 都沒有這個能力（embeddings、圖片、語音、工具呼叫…）。有任何一個 Model 支援就不會丟這個。\"\"\"\n\n\ndef _fail(data, op):\n    msg = data.get(\"error\") or \"橋接呼叫失敗：\" + op\n    if str(msg).startswith(\"NOT_SUPPORTED:\"):\n        raise NotSupported(str(msg)[len(\"NOT_SUPPORTED:\"):].strip())\n    raise BridgeError(msg)\n\n\ndef available():\n    return IN_BROWSER or (bool(RPC_DIR) and os.path.isdir(RPC_DIR))\n\n\ndef sleep(seconds):\n    \"\"\"等一下。在網頁版（Pyodide）不能用 time.sleep（會卡住整個頁面），改用 JS 的計時器。\"\"\"\n    if IN_BROWSER:\n        import asyncio\n        import _fa_pybridge\n        asyncio.run(_fa_pybridge.sleep(int(float(seconds) * 1000)))\n    else:\n        time.sleep(seconds)\n\n\ndef call(op, args=None, timeout=240.0):\n    \"\"\"送一個請求給助理並等回應。op 例如 'pw.goto'、'tool'、'domain'。\"\"\"\n    if IN_BROWSER:\n        import asyncio\n        import _fa_pybridge\n        raw = asyncio.run(_fa_pybridge.call(op, json.dumps(args or {})))\n        data = json.loads(str(raw))\n        if not data.get(\"ok\", False):\n            _fail(data, op)\n        return data.get(\"result\")\n    if not available():\n        raise BridgeError(\"不在 AI 助理的橋接環境裡（沒有 FA_BRIDGE_RPC）。這支腳本要由助理的 run_command（桌面版）或 python_execute 執行。\")\n    rid = uuid.uuid4().hex[:12]\n    req = os.path.join(RPC_DIR, \"req-%s.json\" % rid)\n    res = os.path.join(RPC_DIR, \"res-%s.json\" % rid)\n    tmp = req + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as f:\n        json.dump({\"id\": rid, \"op\": op, \"args\": args or {}}, f, ensure_ascii=False)\n    os.replace(tmp, req)\n    t0 = time.time()\n    delay = 0.03\n    while True:\n        if os.path.exists(res):\n            try:\n                with open(res, \"r\", encoding=\"utf-8\") as f:\n                    data = json.load(f)\n            except (ValueError, OSError):\n                time.sleep(0.05)  # 助理還在寫入\n                continue\n            for p in (res, req):\n                try:\n                    os.remove(p)\n                except OSError:\n                    pass\n            if not data.get(\"ok\", False):\n                _fail(data, op)\n            return data.get(\"result\")\n        if time.time() - t0 > timeout:\n            raise BridgeError(\"橋接逾時（%d 秒沒有回應）：%s\" % (int(timeout), op))\n        time.sleep(delay)\n        delay = min(0.2, delay * 1.5)\n\n\nasync def acall(op, args=None, timeout=240.0):\n    \"\"\"call 的 async 版：網頁版直接 await 助理頁面的 JS（不會卡住事件迴圈）；桌面版把檔案信箱的等待丟到執行緒，不擋住別的 async 工作。\"\"\"\n    if IN_BROWSER:\n        import _fa_pybridge\n        raw = await _fa_pybridge.call(op, json.dumps(args or {}))\n        data = json.loads(str(raw))\n        if not data.get(\"ok\", False):\n            _fail(data, op)\n        return data.get(\"result\")\n    import asyncio\n    loop = asyncio.get_event_loop()\n    return await loop.run_in_executor(None, lambda: call(op, args, timeout))\n\n\ndef install_hooks():\n    \"\"\"裝上轉接用的攔截：直接送 HTTP 的 LLM 呼叫（OpenAI 標準與 Claude 格式）轉給助理的模型；網頁版另外把檔案寫入繞進 fap。可重複呼叫。\"\"\"\n    try:\n        import fa_http\n        fa_http.install()\n    except Exception as e:  # 缺 requests／httpx 之類不是錯誤\n        sys.stderr.write(\"[fa-bridge] http hook: %s\\n\" % e)\n    if IN_BROWSER:\n        try:\n            import fa_fs\n            fa_fs.install()\n        except Exception as e:\n            sys.stderr.write(\"[fa-bridge] fs hook: %s\\n\" % e)\n\n\ndef tool(name, **args):\n    \"\"\"呼叫助理的一個工具（目前開放 browser_* 這組）。回傳工具的結果（已解析的 dict）。\"\"\"\n    return call(\"tool\", {\"name\": name, \"args\": args})\n\n\ndef domain(domain_key, task):\n    \"\"\"把一個任務委派給助理的領域（子 AI，例如 browser_control、desktop_ops）。回傳它的文字結論。\"\"\"\n    return call(\"domain\", {\"domain\": domain_key, \"task\": task}, timeout=900.0)\n","fa_fs.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_fs — 網頁版（Pyodide）的檔案存取：寫入繞進 fap（使用者授權的資料夾）。\n\n網頁版的 Python 跑在瀏覽器裡，只有一個看不到的暫存檔案系統（關掉頁面就消失）。腳本寫出的報告、截圖、資料庫等如果留在那裡，\n使用者永遠拿不到。所以這裡把檔案存取接到 fap：\n  * 明確指定：/fap/<資料夾名稱>/路徑，或 \"fap:<資料夾名稱>/路徑\"\n  * 一般路徑（相對路徑、或不是系統內部用途的絕對路徑）：自動放進「預設的 fap」——設定裡指定的那一個，沒指定就用第一個已授權、可寫入的\n  * 系統內部路徑（/tmp、/proc、/dev、Python 的標準函式庫與套件、轉接層自己）維持在暫存檔案系統，不繞\n沒有任何可寫入的 fap 時，寫入會丟出 PermissionError 並說明怎麼授權（不會悄悄把檔案丟掉）。\n\n做法：open() 讀取時先把 fap 的內容取到暫存、寫入時在關閉檔案的當下送回 fap；os／pathlib 的 exists、stat、listdir、scandir、makedirs、mkdir、\nremove、rmdir、rename、replace 也接上。桌面版 Python 是真的檔案系統，不需要這一層。\n\"\"\"\nimport builtins\nimport io\nimport os\nimport sys\n\nimport fa_bridge\n\n_ST = {\"installed\": False, \"default\": None, \"cache\": \"/fa_fap_cache\"}\n_LOCAL = (\"/tmp\", \"/proc\", \"/dev\", \"/sys\", \"/lib\", \"/usr\", \"/fa_pybridge\", \"/fa_fap_cache\", \"/home/pyodide/.cache\", \"/etc\", \"/var/tmp\", \"/work\")  # /work＝python_execute 的工作目錄（工具自己的輸出管道，不導向 fap）\n_orig = {}\n\n\ndef _call(op, **a):\n    return fa_bridge.call(op, a, timeout=120.0)\n\n\ndef default_label():\n    if _ST[\"default\"] is None:\n        r = _call(\"fs.info\")\n        if not r or not r.get(\"label\"):\n            raise PermissionError((r or {}).get(\"hint\") or \"沒有可以寫入的授權資料夾（fap）。請先在助理的「檔案存取點」授權一個資料夾，或在設定指定 pythonBridgeFap。\")\n        _ST[\"default\"] = r[\"label\"]\n    return _ST[\"default\"]\n\n\ndef _site_dirs():\n    out = [p for p in sys.path if p and p.startswith(\"/\") and (\"site-packages\" in p or \"python3\" in p or p.endswith(\".zip\"))]\n    pre = getattr(sys, \"prefix\", \"\") or \"\"\n    if len(pre) > 1:  # Pyodide 的 sys.prefix 是 \"/\"，不能拿來當前綴（會讓所有路徑都被當成系統路徑）\n        out.append(pre)\n    return out\n\n\ndef classify(path):\n    \"\"\"回傳 (label, rel) 表示要走 fap，或 None 表示維持本地。\"\"\"\n    if not fa_bridge.ACTIVE:\n        return None\n    if isinstance(path, int) or path is None:\n        return None\n    try:\n        p = os.fspath(path)\n    except TypeError:\n        return None\n    if isinstance(p, bytes):\n        p = p.decode(\"utf-8\", \"replace\")\n    if p.startswith(\"fap:\"):\n        rest = p[4:].lstrip(\"/\")\n        label, _, rel = rest.partition(\"/\")\n        return label, rel.strip(\"/\")\n    if p.startswith(\"/fap/\"):\n        rest = p[5:]\n        label, _, rel = rest.partition(\"/\")\n        return label, rel.strip(\"/\")\n    absp = os.path.normpath(os.path.join(os.getcwd(), p)) if not p.startswith(\"/\") else os.path.normpath(p)\n    if any(absp == l or absp.startswith(l + \"/\") for l in _LOCAL) or any(absp.startswith(s) for s in _site_dirs()):\n        return None\n    cwd = os.getcwd().rstrip(\"/\")\n    if absp == cwd or absp.startswith(cwd + \"/\"):\n        rel = absp[len(cwd):].strip(\"/\")\n    else:\n        rel = absp.strip(\"/\")\n    return default_label(), rel\n\n\ndef _cache_path(label, rel):\n    return os.path.join(_ST[\"cache\"], label, rel) if rel else os.path.join(_ST[\"cache\"], label)\n\n\ndef _mk_local(path):\n    d = os.path.dirname(path)\n    if d:\n        _orig[\"makedirs\"](d, exist_ok=True)\n\n\ndef _fetch(label, rel):\n    \"\"\"把 fap 的檔案取到暫存，回傳暫存路徑（fap 沒有這個檔案就回 None）。\"\"\"\n    r = _call(\"fs.read\", label=label, path=rel)\n    if not r or not r.get(\"exists\"):\n        return None\n    import base64\n    cp = _cache_path(label, rel)\n    _mk_local(cp)\n    with _orig[\"open\"](cp, \"wb\") as f:\n        f.write(base64.b64decode(r.get(\"b64\") or \"\"))\n    return cp\n\n\ndef _push(label, rel, cp):\n    import base64\n    with _orig[\"open\"](cp, \"rb\") as f:\n        data = f.read()\n    _call(\"fs.write\", label=label, path=rel, b64=base64.b64encode(data).decode(\"ascii\"))\n\n\nclass _SyncFile(object):\n    \"\"\"寫入模式的檔案：關閉時把內容送回 fap。其餘行為跟真的檔案物件一樣。\"\"\"\n\n    def __init__(self, f, label, rel, cp):\n        self.__dict__.update(_f=f, _label=label, _rel=rel, _cp=cp, _done=False)\n\n    def __getattr__(self, k):\n        return getattr(self.__dict__[\"_f\"], k)\n\n    def __iter__(self):\n        return iter(self.__dict__[\"_f\"])\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        self.close()\n        return False\n\n    def close(self):\n        d = self.__dict__\n        if d[\"_done\"]:\n            return\n        d[\"_done\"] = True\n        d[\"_f\"].close()\n        _push(d[\"_label\"], d[\"_rel\"], d[\"_cp\"])\n\n    def __del__(self):\n        try:\n            self.close()\n        except Exception:\n            pass\n\n\ndef _explicit(path):\n    s = str(os.fspath(path)) if not isinstance(path, int) else \"\"\n    return s.startswith(\"fap:\") or s.startswith(\"/fap/\")\n\n\ndef _local_has(path):\n    \"\"\"沒有明確指定 fap 的路徑，如果本地暫存檔案系統裡已經有（例如 python_execute 放進去的檔案），就維持本地。\"\"\"\n    try:\n        _orig[\"stat\"](path)\n        return True\n    except (OSError, ValueError, TypeError):\n        return False\n\n\ndef _open(file, mode=\"r\", *a, **kw):\n    c = classify(file)\n    if c is None:\n        return _orig[\"open\"](file, mode, *a, **kw)\n    label, rel = c\n    writing = any(m in mode for m in \"wax+\")\n    if not writing and not _explicit(file) and _local_has(file):\n        return _orig[\"open\"](file, mode, *a, **kw)\n    cp = _cache_path(label, rel)\n    if \"w\" in mode or \"x\" in mode:\n        if \"x\" in mode and _call(\"fs.exists\", label=label, path=rel).get(\"exists\"):\n            raise FileExistsError(file)\n        _mk_local(cp)\n        return _SyncFile(_orig[\"open\"](cp, mode, *a, **kw), label, rel, cp)\n    got = _fetch(label, rel)\n    if got is None:\n        if \"a\" in mode or \"+\" in mode and \"r\" not in mode:\n            _mk_local(cp)\n            return _SyncFile(_orig[\"open\"](cp, mode, *a, **kw), label, rel, cp)\n        raise FileNotFoundError(2, \"No such file or directory (fap)\", str(file))\n    f = _orig[\"open\"](cp, mode, *a, **kw)\n    return _SyncFile(f, label, rel, cp) if writing else f\n\n\n# ---- os 層\ndef _stat(path, *a, **kw):\n    c = classify(path)\n    if c is None or (not _explicit(path) and _local_has(path)):\n        return _orig[\"stat\"](path, *a, **kw)\n    label, rel = c\n    r = _call(\"fs.stat\", label=label, path=rel)\n    if not r or not r.get(\"exists\"):\n        raise FileNotFoundError(2, \"No such file or directory (fap)\", str(path))\n    mode = (0o040755 if r.get(\"is_dir\") else 0o100644)\n    t = float(r.get(\"mtime\") or 0) / 1000.0\n    return os.stat_result((mode, 0, 0, 1, 0, 0, int(r.get(\"size\") or 0), t, t, t))\n\n\ndef _listdir(path=\".\"):\n    c = classify(path)\n    if c is None or (not _explicit(path) and _local_has(path)):\n        return _orig[\"listdir\"](path)\n    r = _call(\"fs.list\", label=c[0], path=c[1])\n    if r is None or r.get(\"exists\") is False:\n        raise FileNotFoundError(2, \"No such file or directory (fap)\", str(path))\n    return [e[\"name\"] for e in r.get(\"entries\", [])]\n\n\nclass _Entry(object):\n    def __init__(self, base, e):\n        self.name = e[\"name\"]\n        self.path = os.path.join(base, e[\"name\"])\n        self._dir = bool(e.get(\"is_dir\"))\n\n    def is_dir(self, follow_symlinks=True):\n        return self._dir\n\n    def is_file(self, follow_symlinks=True):\n        return not self._dir\n\n    def is_symlink(self):\n        return False\n\n    def stat(self, follow_symlinks=True):\n        return _stat(self.path)\n\n    def __fspath__(self):\n        return self.path\n\n\nclass _ScanIter(object):\n    def __init__(self, items):\n        self._it = iter(items)\n\n    def __iter__(self):\n        return self\n\n    def __next__(self):\n        return next(self._it)\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        return False\n\n    def close(self):\n        pass\n\n\ndef _scandir(path=\".\"):\n    c = classify(path)\n    if c is None or (not _explicit(path) and _local_has(path)):\n        return _orig[\"scandir\"](path)\n    r = _call(\"fs.list\", label=c[0], path=c[1])\n    if r is None or r.get(\"exists\") is False:\n        raise FileNotFoundError(2, \"No such file or directory (fap)\", str(path))\n    base = os.fspath(path)\n    return _ScanIter([_Entry(base, e) for e in r.get(\"entries\", [])])\n\n\ndef _makedirs(name, mode=0o777, exist_ok=False):\n    c = classify(name)\n    if c is None:\n        return _orig[\"makedirs\"](name, mode, exist_ok)\n    if _call(\"fs.exists\", label=c[0], path=c[1]).get(\"exists\") and not exist_ok:\n        raise FileExistsError(17, \"File exists (fap)\", str(name))\n    _call(\"fs.mkdir\", label=c[0], path=c[1])\n\n\ndef _mkdir(path, mode=0o777, *a, **kw):\n    c = classify(path)\n    if c is None:\n        return _orig[\"mkdir\"](path, mode, *a, **kw)\n    if _call(\"fs.exists\", label=c[0], path=c[1]).get(\"exists\"):\n        raise FileExistsError(17, \"File exists (fap)\", str(path))\n    _call(\"fs.mkdir\", label=c[0], path=c[1])\n\n\ndef _remove(path, *a, **kw):\n    c = classify(path)\n    if c is None:\n        return _orig[\"remove\"](path, *a, **kw)\n    r = _call(\"fs.remove\", label=c[0], path=c[1])\n    if not r or not r.get(\"removed\"):\n        raise FileNotFoundError(2, \"No such file or directory (fap)\", str(path))\n    cp = _cache_path(*c)\n    if os.path.exists(cp):\n        try:\n            _orig[\"remove\"](cp)\n        except OSError:\n            pass\n\n\ndef _rename(src, dst, *a, **kw):\n    cs, cd = classify(src), classify(dst)\n    if cs is None and cd is None:\n        return _orig[\"rename\"](src, dst, *a, **kw)\n    with _open(src, \"rb\") as f:\n        data = f.read()\n    with _open(dst, \"wb\") as g:\n        g.write(data)\n    _remove(src)\n\n\ndef install():\n    if _ST[\"installed\"]:\n        return\n    _ST[\"installed\"] = True\n    for k, mod, name in ((\"open\", builtins, \"open\"), (\"stat\", os, \"stat\"), (\"listdir\", os, \"listdir\"), (\"scandir\", os, \"scandir\"),\n                         (\"makedirs\", os, \"makedirs\"), (\"mkdir\", os, \"mkdir\"), (\"remove\", os, \"remove\"), (\"rename\", os, \"rename\")):\n        _orig[k] = getattr(mod, name)\n    builtins.open = _open\n    io.open = _open\n    os.stat = _stat\n    os.listdir = _listdir\n    os.scandir = _scandir\n    os.makedirs = _makedirs\n    os.mkdir = _mkdir\n    os.remove = _remove\n    os.unlink = _remove\n    os.rmdir = _remove\n    os.rename = _rename\n    os.replace = _rename\n    try:\n        _orig[\"makedirs\"](_ST[\"cache\"], exist_ok=True)\n    except OSError:\n        pass\n","fa_http.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_http — 直接送 HTTP 的 LLM 呼叫也轉給助理的模型。\n\n有些腳本不用 openai／anthropic 套件，而是自己用 requests／httpx／urllib 打 API：\n    requests.post(\"https://api.openai.com/v1/chat/completions\", headers={\"Authorization\": ...}, json={...})\n    requests.post(\"https://api.anthropic.com/v1/messages\", headers={\"x-api-key\": ..., \"anthropic-version\": ...}, json={...})\n或打自己架的相容伺服器（任何主機，路徑長得一樣就算）。這裡攔截這些呼叫，**不真的連出去**，改由助理已設定的 LLM Model 回答，\n回傳的格式跟被呼叫的端點一樣（OpenAI 標準或 Claude 格式；一般回應與串流 SSE 都支援）。\n\n支援的端點（路徑後綴比對，前面的 /v1、/openai/v1 之類不拘）：\n  OpenAI 標準：POST /chat/completions、/responses、/completions、/embeddings、/images/generations|edits|variations、\n               /audio/transcriptions|translations|speech、/moderations；GET /models\n  Claude：     POST /messages（含 stream）、/messages/count_tokens\nembeddings、圖片、語音、工具呼叫一律先從已設定的 LLM Model 清單找有這個能力的 Model，全部都不支援才回 501。\n不是這些路徑的請求完全不碰（照原本連網）。想讓某個主機不被攔截：環境變數 FA_HTTP_BYPASS_HOSTS=host1,host2。\n\"\"\"\nimport base64\nimport io\nimport json\nimport os\nimport re\nimport sys\n\nimport fa_bridge\nimport fa_llm\nimport fa_net\nimport fa_sim\nimport fa_ws\n\n_INSTALLED = {\"done\": False, \"hooked\": set()}\n\n\n# ---------------------------------------------------------------- multipart 解析（圖片編輯、語音轉文字會用到）\ndef parse_multipart(body, content_type):\n    m = re.search(r'boundary=\"?([^\";]+)\"?', content_type or \"\")\n    if not m:\n        return {}, []\n    boundary = (\"--\" + m.group(1)).encode()\n    fields, files = {}, []\n    for part in body.split(boundary):\n        part = part.strip(b\"\\r\\n\")\n        if not part or part == b\"--\":\n            continue\n        head, _, data = part.partition(b\"\\r\\n\\r\\n\")\n        h = head.decode(\"utf-8\", \"replace\")\n        name = re.search(r'name=\"([^\"]*)\"', h)\n        fn = re.search(r'filename=\"([^\"]*)\"', h)\n        ct = re.search(r\"Content-Type:\\s*([^\\r\\n]+)\", h, re.I)\n        if data.endswith(b\"\\r\\n\"):\n            data = data[:-2]\n        if fn:\n            files.append({\"name\": name.group(1) if name else \"file\", \"filename\": fn.group(1), \"type\": ct.group(1).strip() if ct else \"application/octet-stream\",\n                          \"b64\": base64.b64encode(data).decode(\"ascii\")})\n        elif name:\n            fields[name.group(1)] = data.decode(\"utf-8\", \"replace\")\n    return fields, files\n\n\ndef _err(status, message, style):\n    if style == \"anthropic\":\n        body = {\"type\": \"error\", \"error\": {\"type\": \"api_error\" if status != 501 else \"not_supported_error\", \"message\": message}}\n    else:\n        body = {\"error\": {\"message\": message, \"type\": \"not_supported\" if status == 501 else \"api_error\", \"param\": None, \"code\": \"not_supported\" if status == 501 else None}}\n    return status, {\"content-type\": \"application/json\"}, json.dumps(body, ensure_ascii=False).encode(\"utf-8\")\n\n\ndef _status_of(e):\n    if isinstance(e, fa_bridge.NotSupported):\n        return 501\n    m = re.search(r\"API錯誤\\((\\d{3})\\)\", str(e))\n    return int(m.group(1)) if m else 502\n\n\ndef _json(obj, status=200):\n    return status, {\"content-type\": \"application/json\"}, json.dumps(obj, ensure_ascii=False).encode(\"utf-8\")\n\n\ndef _sse(events, done):\n    return 200, {\"content-type\": \"text/event-stream\", \"cache-control\": \"no-cache\"}, fa_llm.sse(events, done=done).encode(\"utf-8\")\n\n\n# ---------------------------------------------------------------- 路由\n_ROUTES = [\n    (\"POST\", re.compile(r\"/messages/count_tokens/?$\"), \"count_tokens\"),\n    (\"POST\", re.compile(r\"/messages/?$\"), \"anthropic\"),\n    (\"POST\", re.compile(r\"/chat/completions/?$\"), \"chat\"),\n    (\"POST\", re.compile(r\"/responses/?$\"), \"responses\"),\n    (\"POST\", re.compile(r\"/completions/?$\"), \"completions\"),\n    (\"POST\", re.compile(r\"/embeddings/?$\"), \"embeddings\"),\n    (\"POST\", re.compile(r\"/images/(generations|edits|variations)/?$\"), \"images\"),\n    (\"POST\", re.compile(r\"/audio/(transcriptions|translations|speech)/?$\"), \"audio\"),\n    (\"POST\", re.compile(r\"/moderations/?$\"), \"moderations\"),\n    (\"GET\", re.compile(r\"/models/?$\"), \"models\"),\n]\n\n\ndef route(method, url, headers=None, body=b\"\"):\n    \"\"\"先看是不是 LLM 端點（回 (status, headers, body_bytes)），再看是不是要接手的一般 HTTP（本機 mock 伺服器、網頁版的外部網址；見 fa_net）。都不是就回 None。\"\"\"\n    r = _route_llm(method, url, headers, body)\n    return r if r is not None else fa_net.route(method, url, headers, body)\n\n\ndef _route_llm(method, url, headers=None, body=b\"\"):\n    \"\"\"是 LLM 端點就回 (status, headers, body_bytes)，不是就回 None。\"\"\"\n    if not fa_bridge.ACTIVE:\n        return None\n    try:\n        from urllib.parse import urlparse\n        u = urlparse(url)\n    except Exception:\n        return None\n    if not u.scheme.startswith(\"http\"):\n        return None\n    bypass = [h.strip().lower() for h in os.environ.get(\"FA_HTTP_BYPASS_HOSTS\", \"\").split(\",\") if h.strip()]\n    if (u.hostname or \"\").lower() in bypass:\n        return None\n    method = (method or \"GET\").upper()\n    kind = None\n    for m, rx, k in _ROUTES:\n        if m == method and rx.search(u.path):\n            kind = k\n            m_ = rx.search(u.path)\n            break\n    if kind is None:\n        return None\n    ct = \"\"\n    for k, v in (headers or {}).items():\n        if str(k).lower() == \"content-type\":\n            ct = str(v)\n    if isinstance(body, str):\n        body = body.encode(\"utf-8\")\n    body = body or b\"\"\n    style = \"anthropic\" if kind in (\"anthropic\", \"count_tokens\") else \"openai\"\n    data = {}\n    fields, files = {}, []\n    if kind not in (\"models\",):\n        if \"multipart/form-data\" in ct:\n            fields, files = parse_multipart(body, ct)\n        else:\n            try:\n                data = json.loads(body.decode(\"utf-8\") or \"{}\")\n            except ValueError:\n                return None\n            if not isinstance(data, dict):\n                return None\n    # 保險：看起來不像 LLM 請求就不碰（例如別的服務剛好也有 /messages 這種路徑）\n    if kind == \"anthropic\" and not (\"messages\" in data and (\"model\" in data or \"max_tokens\" in data)):\n        return None\n    if kind == \"count_tokens\" and \"messages\" not in data:\n        return None\n    if kind == \"chat\" and \"messages\" not in data:\n        return None\n    if kind == \"responses\" and \"input\" not in data and \"instructions\" not in data:\n        return None\n    if kind == \"completions\" and \"prompt\" not in data:\n        return None\n    try:\n        return _handle(kind, m_, data, fields, files, u)\n    except Exception as e:\n        return _err(_status_of(e), str(e), style)\n\n\ndef _handle(kind, m, data, fields, files, u):\n    if kind == \"chat\":\n        d = dict(data)\n        stream, so = d.pop(\"stream\", False), d.pop(\"stream_options\", None)\n        r = fa_llm.complete(fa_llm.chat_request(d.pop(\"model\", None), d.pop(\"messages\"), **d))\n        r.setdefault(\"object\", \"chat.completion\")\n        if stream:\n            return _sse(fa_llm.chat_chunks(r, include_usage=bool((so or {}).get(\"include_usage\"))), done=True)\n        return _json(r)\n    if kind == \"responses\":\n        d = dict(data)\n        stream = d.pop(\"stream\", False)\n        r = fa_llm.complete(fa_llm.responses_to_chat(model=d.pop(\"model\", None), input=d.pop(\"input\", None), instructions=d.pop(\"instructions\", None), **d))\n        resp = fa_llm.chat_to_response(r, data.get(\"model\"))\n        return _sse(fa_llm.response_events(resp), done=False) if stream else _json(resp)\n    if kind == \"completions\":\n        d = dict(data)\n        stream = d.pop(\"stream\", False)\n        r = fa_llm.complete(fa_llm.completions_to_chat(d.pop(\"prompt\"), model=d.pop(\"model\", None), **{k: v for k, v in d.items() if k in (\"temperature\", \"max_tokens\", \"top_p\", \"stop\", \"n\", \"seed\")}))\n        out = fa_llm.chat_to_completion(r)\n        return _json(out)\n    if kind == \"anthropic\":\n        d = dict(data)\n        stream = d.pop(\"stream\", False)\n        r = fa_llm.complete(fa_llm.anthropic_to_chat(**d))\n        msg = fa_llm.chat_to_anthropic(r, data.get(\"model\"))\n        return _sse(fa_llm.anthropic_events(msg), done=False) if stream else _json(msg)\n    if kind == \"count_tokens\":\n        return _json({\"input_tokens\": fa_llm.estimate_tokens({\"s\": data.get(\"system\"), \"m\": data.get(\"messages\")})})\n    if kind == \"embeddings\":\n        r = fa_llm.upstream(\"embeddings\", \"/embeddings\", json_body=data)\n        return _json(r.get(\"json\") or {})\n    if kind == \"images\":\n        sub = m.group(1)\n        path = \"/images/\" + sub\n        if files:\n            r = fa_llm.upstream(\"images\", path, form={\"fields\": fields, \"files\": files})\n        else:\n            r = fa_llm.upstream(\"images\", path, json_body=data)\n        return _json(r.get(\"json\") or {})\n    if kind == \"audio\":\n        sub = m.group(1)\n        if sub == \"speech\":\n            r = fa_llm.upstream(\"audio_speech\", \"/audio/speech\", json_body=data, want=\"bytes\")\n            return 200, {\"content-type\": r.get(\"content_type\") or \"audio/mpeg\"}, base64.b64decode(r.get(\"b64\") or \"\")\n        fmt = fields.get(\"response_format\")\n        r = fa_llm.upstream(\"audio_transcribe\", \"/audio/\" + sub, form={\"fields\": fields, \"files\": files}, want=\"bytes\" if fmt in (\"text\", \"srt\", \"vtt\") else \"json\")\n        if fmt in (\"text\", \"srt\", \"vtt\"):\n            return 200, {\"content-type\": \"text/plain; charset=utf-8\"}, base64.b64decode(r.get(\"b64\") or \"\")\n        return _json(r.get(\"json\") or {})\n    if kind == \"moderations\":\n        return _json(fa_sim.moderation(**{k: v for k, v in data.items() if k in (\"input\", \"model\")}))\n    if kind == \"models\":\n        return _json(fa_sim.models(fa_bridge.call(\"llm.info\", {}, timeout=10.0).get(\"model\"))[0])\n    return None\n\n\n# ---------------------------------------------------------------- 安裝：requests／httpx／urllib（模組之後才被 import 也會補上）\ndef _patch_requests():\n    import requests\n    from requests import Session\n    if getattr(Session.send, \"_fa_patched\", False):\n        return\n    orig = Session.send\n\n    def send(self, request, **kw):\n        hdrs = dict(request.headers or {})\n        r = route(request.method, request.url, hdrs, request.body if not hasattr(request.body, \"read\") else request.body.read())\n        if r is None:\n            return orig(self, request, **kw)\n        status, h, body = r\n        resp = requests.Response()\n        resp.status_code = status\n        resp._content = body\n        resp.headers = requests.structures.CaseInsensitiveDict(h)\n        resp.url = request.url\n        resp.request = request\n        resp.encoding = \"utf-8\"\n        resp.raw = io.BytesIO(body)\n        resp.reason = \"OK\" if status < 400 else \"Error\"\n        return resp\n    send._fa_patched = True\n    Session.send = send\n\n\ndef _patch_httpx():\n    import httpx\n    for cls_name, is_async in ((\"Client\", False), (\"AsyncClient\", True)):\n        cls = getattr(httpx, cls_name, None)\n        if cls is None or getattr(cls.send, \"_fa_patched\", False):\n            continue\n        orig = cls.send\n        if is_async:\n            async def send(self, request, *a, __orig=orig, **kw):\n                r = route(request.method, str(request.url), dict(request.headers), request.content if hasattr(request, \"content\") else b\"\")\n                if r is None:\n                    return await __orig(self, request, *a, **kw)\n                return httpx.Response(r[0], headers=r[1], content=r[2], request=request)\n        else:\n            def send(self, request, *a, __orig=orig, **kw):\n                r = route(request.method, str(request.url), dict(request.headers), request.read() if hasattr(request, \"read\") else b\"\")\n                if r is None:\n                    return __orig(self, request, *a, **kw)\n                return httpx.Response(r[0], headers=r[1], content=r[2], request=request)\n        send._fa_patched = True\n        cls.send = send\n\n\ndef _patch_urllib():\n    import urllib.request\n    import urllib.response\n    import urllib.error\n    import email.message\n    if getattr(urllib.request.urlopen, \"_fa_patched\", False):\n        return\n    orig = urllib.request.urlopen\n\n    def urlopen(url, data=None, *a, **kw):\n        req = url if isinstance(url, urllib.request.Request) else None\n        full = req.full_url if req else url\n        method = req.get_method() if req else (\"POST\" if data is not None else \"GET\")\n        body = data if data is not None else (req.data if req else None)\n        hdrs = dict(req.header_items()) if req else {}\n        r = route(method, full, hdrs, body or b\"\")\n        if r is None:\n            return orig(url, data, *a, **kw)\n        status, h, payload = r\n        msg = email.message.Message()\n        for k, v in h.items():\n            msg[k] = v\n        resp = urllib.response.addinfourl(io.BytesIO(payload), msg, full, status)\n        if status >= 400:\n            raise urllib.error.HTTPError(full, status, \"Error\", msg, io.BytesIO(payload))\n        return resp\n    urlopen._fa_patched = True\n    urllib.request.urlopen = urlopen\n\n\n_PATCHERS = {\"requests\": _patch_requests, \"httpx\": _patch_httpx, \"websocket\": fa_ws.patch_websocket_client, \"websockets\": fa_ws.patch_websockets}\n\n\nclass _OnImport(object):\n    \"\"\"requests／httpx 在安裝轉接之後才被 import（例如 Pyodide 裡 micropip 現裝）時，import 完成後補上攔截。\"\"\"\n\n    def find_spec(self, name, path=None, target=None):\n        if name not in _PATCHERS or name in _INSTALLED[\"hooked\"]:\n            return None\n        import importlib.util\n        _INSTALLED[\"hooked\"].add(name)\n        try:\n            spec = importlib.util.find_spec(name)\n        finally:\n            _INSTALLED[\"hooked\"].discard(name)\n        if spec is None or spec.loader is None:\n            return None\n        loader = spec.loader\n        orig_exec = loader.exec_module\n\n        def exec_module(module, _o=orig_exec, _n=name):\n            _o(module)\n            try:\n                _PATCHERS[_n]()\n            except Exception as e:\n                sys.stderr.write(\"[fa-bridge] patch %s: %s\\n\" % (_n, e))\n        try:\n            loader.exec_module = exec_module\n        except Exception:\n            return None\n        return spec\n\n\ndef install():\n    if _INSTALLED[\"done\"]:\n        return\n    _INSTALLED[\"done\"] = True\n    try:\n        fa_net.install()\n    except Exception as e:\n        sys.stderr.write(\"[fa-bridge] patch http.client: %s\\n\" % e)\n    try:\n        _patch_urllib()\n    except Exception as e:\n        sys.stderr.write(\"[fa-bridge] patch urllib: %s\\n\" % e)\n    for name, fn in _PATCHERS.items():\n        if name in sys.modules:\n            try:\n                fn()\n            except Exception as e:\n                sys.stderr.write(\"[fa-bridge] patch %s: %s\\n\" % (name, e))\n        else:\n            import importlib.util\n            try:\n                if importlib.util.find_spec(name) is not None:\n                    try:\n                        fn()\n                    except Exception as e:\n                        sys.stderr.write(\"[fa-bridge] patch %s: %s\\n\" % (name, e))\n            except Exception:\n                pass\n    if not any(isinstance(f, _OnImport) for f in sys.meta_path):\n        sys.meta_path.insert(0, _OnImport())\n","fa_llm.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_llm — LLM API 的格式轉換與串流模擬（只用標準函式庫）。\n\n助理實際使用的模型走「OpenAI 相容的 chat/completions」。腳本卻可能用各種寫法呼叫 LLM：\n  * OpenAI 標準：chat.completions、responses、completions（舊）、embeddings\n  * Claude（Anthropic）：messages\n這個模組把它們全部轉成同一種請求（chat/completions），再把回應轉回腳本期待的格式，所以不管腳本用哪一種，\n實際上都是助理目前選用的那個模型在回答。\n\n兩種呼叫方式都支援：Python 套件（openai／anthropic，同步與 async）與直接送 HTTP（requests／httpx／urllib，見 fa_http.py）。\n\"\"\"\nimport json\nimport time\nimport uuid\n\nimport fa_bridge\n\n\n# ---------------------------------------------------------------- 小工具\ndef _id(prefix):\n    return \"%s_%s\" % (prefix, uuid.uuid4().hex[:24])\n\n\ndef _now():\n    return int(time.time())\n\n\ndef text_of(content):\n    \"\"\"把各種 content 形式（字串、區塊清單）變成純文字。\"\"\"\n    if content is None:\n        return \"\"\n    if isinstance(content, str):\n        return content\n    if isinstance(content, list):\n        out = []\n        for b in content:\n            if isinstance(b, str):\n                out.append(b)\n            elif isinstance(b, dict):\n                t = b.get(\"type\")\n                if t in (\"text\", \"input_text\", \"output_text\") or (\"text\" in b and t is None):\n                    out.append(str(b.get(\"text\", \"\")))\n                elif t == \"tool_result\":\n                    out.append(text_of(b.get(\"content\")))\n        return \"\".join(out)\n    if isinstance(content, dict):\n        return str(content.get(\"text\", \"\"))\n    return str(content)\n\n\ndef estimate_tokens(text):\n    \"\"\"沒有真正的 tokenizer 時的粗估：英文約 4 字元一個 token，中日韓字約 1.3 字一個。\"\"\"\n    s = text if isinstance(text, str) else json.dumps(text, ensure_ascii=False)\n    cjk = sum(1 for ch in s if \"぀\" <= ch <= \"鿿\" or \"가\" <= ch <= \"힯\")\n    return max(1, int(cjk / 1.3 + (len(s) - cjk) / 4.0))\n\n\n# ---------------------------------------------------------------- 呼叫助理的模型\ndef complete(req, timeout=600.0):\n    \"\"\"req 是 OpenAI chat/completions 形式的 dict；回傳 OpenAI chat.completion 形式的 dict。\"\"\"\n    return fa_bridge.call(\"llm.complete\", req, timeout=timeout)\n\n\nasync def acomplete(req, timeout=600.0):\n    return await fa_bridge.acall(\"llm.complete\", req, timeout=timeout)\n\n\ndef upstream(cap, path, json_body=None, form=None, want=\"json\", method=\"POST\", timeout=600.0):\n    \"\"\"把一個 OpenAI 標準的 HTTP 呼叫轉給助理「已設定的 LLM Model 清單」裡有這個能力的那一個（依序試，第一個成功的就用）。\n    cap：embeddings、images、audio_transcribe、audio_speech、chat、tools、vision。\n    所有 Model 都不支援才會丟 fa_bridge.NotSupported。回傳 {status, content_type, json | b64, model}。\"\"\"\n    return fa_bridge.call(\"llm.upstream\", {\"cap\": cap, \"path\": path, \"method\": method, \"json\": json_body, \"form\": form, \"want\": want}, timeout=timeout)\n\n\nasync def aupstream(cap, path, json_body=None, form=None, want=\"json\", method=\"POST\", timeout=600.0):\n    return await fa_bridge.acall(\"llm.upstream\", {\"cap\": cap, \"path\": path, \"method\": method, \"json\": json_body, \"form\": form, \"want\": want}, timeout=timeout)\n\n\ndef file_part(name, file, default_filename=\"file\", default_type=\"application/octet-stream\"):\n    \"\"\"把腳本給的檔案（bytes、路徑、檔案物件、(檔名, 內容[, 類型]) 元組）變成可以傳過橋接的表單檔案。\"\"\"\n    import base64\n    import mimetypes\n    import os\n    filename, data, ctype = default_filename, None, None\n    if isinstance(file, tuple):\n        filename = file[0] or filename\n        data = file[1] if len(file) > 1 else b\"\"\n        ctype = file[2] if len(file) > 2 else None\n    else:\n        data = file\n    if isinstance(data, str) and os.path.exists(data):\n        filename = os.path.basename(data)\n        data = open(data, \"rb\").read()\n    elif hasattr(data, \"read\"):\n        filename = os.path.basename(str(getattr(data, \"name\", filename)))\n        data = data.read()\n    elif hasattr(data, \"__fspath__\"):\n        filename = os.path.basename(str(data))\n        data = open(data, \"rb\").read()\n    if isinstance(data, str):\n        data = data.encode(\"utf-8\")\n    ctype = ctype or mimetypes.guess_type(filename)[0] or default_type\n    return {\"name\": name, \"filename\": filename, \"type\": ctype, \"b64\": base64.b64encode(data or b\"\").decode(\"ascii\")}\n\n\ndef note_simulated(api):\n    \"\"\"告訴助理：這個呼叫是模擬的（助理沒有對應能力），讓上層 AI 知道結果不是真的。\"\"\"\n    try:\n        fa_bridge.call(\"sim.note\", {\"api\": api}, timeout=10.0)\n    except Exception:\n        pass\n\n\n# ---------------------------------------------------------------- OpenAI chat 的清理\n_CHAT_KEYS = (\"messages\", \"temperature\", \"top_p\", \"max_tokens\", \"stop\", \"tools\", \"tool_choice\", \"response_format\",\n              \"n\", \"presence_penalty\", \"frequency_penalty\", \"seed\", \"user\", \"logit_bias\", \"parallel_tool_calls\")\n\n\ndef chat_request(model=None, messages=None, **kw):\n    \"\"\"整理成可以送去上游的 chat/completions 請求（丟掉上游不一定認得的欄位）。\"\"\"\n    req = {\"messages\": list(messages or [])}\n    if kw.get(\"max_completion_tokens\") is not None and kw.get(\"max_tokens\") is None:\n        kw[\"max_tokens\"] = kw[\"max_completion_tokens\"]\n    for k in _CHAT_KEYS:\n        if k == \"messages\":\n            continue\n        v = kw.get(k)\n        if v is not None:\n            req[k] = v\n    if model:\n        req[\"_requested_model\"] = model\n    return req\n\n\ndef chat_chunks(resp, chunk_chars=24, include_usage=False):\n    \"\"\"把一個完整的 chat.completion 變成串流的 chunk（模擬串流：上游先整段回來，再分段送出）。\"\"\"\n    cid = resp.get(\"id\") or _id(\"chatcmpl\")\n    model = resp.get(\"model\") or \"assistant\"\n    created = resp.get(\"created\") or _now()\n    base = {\"id\": cid, \"object\": \"chat.completion.chunk\", \"created\": created, \"model\": model}\n    for ch in resp.get(\"choices\") or [{}]:\n        idx = ch.get(\"index\", 0)\n        msg = ch.get(\"message\") or {}\n        yield dict(base, choices=[{\"index\": idx, \"delta\": {\"role\": \"assistant\", \"content\": \"\"}, \"finish_reason\": None}])\n        text = text_of(msg.get(\"content\"))\n        for i in range(0, len(text), max(1, chunk_chars)):\n            yield dict(base, choices=[{\"index\": idx, \"delta\": {\"content\": text[i:i + chunk_chars]}, \"finish_reason\": None}])\n        for ti, tc in enumerate(msg.get(\"tool_calls\") or []):\n            fn = tc.get(\"function\") or {}\n            yield dict(base, choices=[{\"index\": idx, \"delta\": {\"tool_calls\": [{\"index\": ti, \"id\": tc.get(\"id\") or _id(\"call\"), \"type\": \"function\",\n                                                                              \"function\": {\"name\": fn.get(\"name\", \"\"), \"arguments\": fn.get(\"arguments\", \"\")}}]},\n                                       \"finish_reason\": None}])\n        yield dict(base, choices=[{\"index\": idx, \"delta\": {}, \"finish_reason\": ch.get(\"finish_reason\") or \"stop\"}])\n    if include_usage:\n        yield dict(base, choices=[], usage=resp.get(\"usage\") or {})\n\n\n# ---------------------------------------------------------------- 舊的 completions\ndef completions_to_chat(prompt, **kw):\n    if isinstance(prompt, list):\n        prompt = \"\\n\".join(str(p) for p in prompt)\n    return chat_request(messages=[{\"role\": \"user\", \"content\": str(prompt or \"\")}], **kw)\n\n\ndef chat_to_completion(resp):\n    return {\"id\": (resp.get(\"id\") or _id(\"cmpl\")).replace(\"chatcmpl\", \"cmpl\"), \"object\": \"text_completion\", \"created\": resp.get(\"created\") or _now(),\n            \"model\": resp.get(\"model\") or \"assistant\",\n            \"choices\": [{\"text\": text_of((c.get(\"message\") or {}).get(\"content\")), \"index\": c.get(\"index\", 0), \"logprobs\": None,\n                         \"finish_reason\": c.get(\"finish_reason\") or \"stop\"} for c in resp.get(\"choices\") or []],\n            \"usage\": resp.get(\"usage\") or {}}\n\n\n# ---------------------------------------------------------------- OpenAI Responses API\ndef _resp_content_to_chat(content):\n    if isinstance(content, str):\n        return content\n    parts = []\n    for b in content or []:\n        t = b.get(\"type\") if isinstance(b, dict) else None\n        if t in (\"input_text\", \"output_text\", \"text\"):\n            parts.append({\"type\": \"text\", \"text\": b.get(\"text\", \"\")})\n        elif t == \"input_image\":\n            url = b.get(\"image_url\") or b.get(\"url\") or \"\"\n            parts.append({\"type\": \"image_url\", \"image_url\": {\"url\": url if isinstance(url, str) else (url or {}).get(\"url\", \"\")}})\n    if all(p[\"type\"] == \"text\" for p in parts):\n        return \"\".join(p[\"text\"] for p in parts)\n    return parts\n\n\ndef responses_to_chat(model=None, input=None, instructions=None, **kw):\n    msgs = []\n    if instructions:\n        msgs.append({\"role\": \"system\", \"content\": str(instructions)})\n    if isinstance(input, str):\n        msgs.append({\"role\": \"user\", \"content\": input})\n    else:\n        for it in input or []:\n            t = it.get(\"type\", \"message\") if isinstance(it, dict) else \"message\"\n            if t == \"message\" or \"role\" in it:\n                role = it.get(\"role\", \"user\")\n                msgs.append({\"role\": \"system\" if role == \"developer\" else role, \"content\": _resp_content_to_chat(it.get(\"content\"))})\n            elif t == \"function_call\":\n                msgs.append({\"role\": \"assistant\", \"content\": None, \"tool_calls\": [{\"id\": it.get(\"call_id\") or it.get(\"id\") or _id(\"call\"), \"type\": \"function\",\n                                                                                     \"function\": {\"name\": it.get(\"name\", \"\"), \"arguments\": it.get(\"arguments\", \"{}\")}}]})\n            elif t == \"function_call_output\":\n                msgs.append({\"role\": \"tool\", \"tool_call_id\": it.get(\"call_id\", \"\"), \"content\": text_of(it.get(\"output\"))})\n    tools = None\n    if kw.get(\"tools\"):\n        tools = []\n        for t in kw[\"tools\"]:\n            if t.get(\"type\") == \"function\":\n                fn = t.get(\"function\") or {\"name\": t.get(\"name\"), \"description\": t.get(\"description\", \"\"), \"parameters\": t.get(\"parameters\") or {\"type\": \"object\", \"properties\": {}}}\n                tools.append({\"type\": \"function\", \"function\": fn})\n    rf = None\n    fmt = (kw.get(\"text\") or {}).get(\"format\") if isinstance(kw.get(\"text\"), dict) else None\n    if isinstance(fmt, dict) and fmt.get(\"type\") in (\"json_object\", \"json_schema\"):\n        rf = {\"type\": fmt[\"type\"]}\n        if fmt[\"type\"] == \"json_schema\":\n            rf[\"json_schema\"] = {\"name\": fmt.get(\"name\", \"output\"), \"schema\": fmt.get(\"schema\") or {}, \"strict\": bool(fmt.get(\"strict\"))}\n    return chat_request(model=model, messages=msgs, temperature=kw.get(\"temperature\"), top_p=kw.get(\"top_p\"),\n                        max_tokens=kw.get(\"max_output_tokens\"), tools=tools, tool_choice=kw.get(\"tool_choice\"), response_format=rf)\n\n\ndef chat_to_response(resp, requested=None):\n    ch = (resp.get(\"choices\") or [{}])[0]\n    msg = ch.get(\"message\") or {}\n    text = text_of(msg.get(\"content\"))\n    rid = _id(\"resp\")\n    output = []\n    if text or not msg.get(\"tool_calls\"):\n        output.append({\"id\": _id(\"msg\"), \"type\": \"message\", \"status\": \"completed\", \"role\": \"assistant\",\n                       \"content\": [{\"type\": \"output_text\", \"text\": text, \"annotations\": []}]})\n    for tc in msg.get(\"tool_calls\") or []:\n        fn = tc.get(\"function\") or {}\n        output.append({\"id\": _id(\"fc\"), \"type\": \"function_call\", \"status\": \"completed\", \"call_id\": tc.get(\"id\") or _id(\"call\"),\n                       \"name\": fn.get(\"name\", \"\"), \"arguments\": fn.get(\"arguments\", \"{}\")})\n    u = resp.get(\"usage\") or {}\n    pt, ct = u.get(\"prompt_tokens\") or 0, u.get(\"completion_tokens\") or 0\n    return {\"id\": rid, \"object\": \"response\", \"created_at\": resp.get(\"created\") or _now(), \"status\": \"completed\", \"error\": None,\n            \"model\": resp.get(\"model\") or requested or \"assistant\", \"output\": output, \"output_text\": text,\n            \"usage\": {\"input_tokens\": pt, \"output_tokens\": ct, \"total_tokens\": u.get(\"total_tokens\") or (pt + ct)}}\n\n\ndef response_events(r, chunk_chars=24):\n    \"\"\"Responses API 的串流事件（模擬）。\"\"\"\n    seq = 0\n\n    def ev(t, **kw):\n        nonlocal seq\n        seq += 1\n        d = {\"type\": t, \"sequence_number\": seq}\n        d.update(kw)\n        return d\n    skeleton = dict(r, status=\"in_progress\", output=[], output_text=\"\")\n    yield ev(\"response.created\", response=skeleton)\n    yield ev(\"response.in_progress\", response=skeleton)\n    for oi, item in enumerate(r.get(\"output\") or []):\n        yield ev(\"response.output_item.added\", output_index=oi, item=dict(item, status=\"in_progress\", content=[]) if item[\"type\"] == \"message\" else item)\n        if item[\"type\"] == \"message\":\n            yield ev(\"response.content_part.added\", output_index=oi, content_index=0, item_id=item[\"id\"], part={\"type\": \"output_text\", \"text\": \"\", \"annotations\": []})\n            t = item[\"content\"][0][\"text\"]\n            for i in range(0, len(t), max(1, chunk_chars)):\n                yield ev(\"response.output_text.delta\", output_index=oi, content_index=0, item_id=item[\"id\"], delta=t[i:i + chunk_chars])\n            yield ev(\"response.output_text.done\", output_index=oi, content_index=0, item_id=item[\"id\"], text=t)\n            yield ev(\"response.content_part.done\", output_index=oi, content_index=0, item_id=item[\"id\"], part=item[\"content\"][0])\n        elif item[\"type\"] == \"function_call\":\n            yield ev(\"response.function_call_arguments.delta\", output_index=oi, item_id=item[\"id\"], delta=item.get(\"arguments\", \"\"))\n            yield ev(\"response.function_call_arguments.done\", output_index=oi, item_id=item[\"id\"], arguments=item.get(\"arguments\", \"\"))\n        yield ev(\"response.output_item.done\", output_index=oi, item=item)\n    yield ev(\"response.completed\", response=r)\n\n\n# ---------------------------------------------------------------- Anthropic（Claude）messages\n_STOP_MAP = {\"stop\": \"end_turn\", \"length\": \"max_tokens\", \"tool_calls\": \"tool_use\", \"function_call\": \"tool_use\", \"content_filter\": \"refusal\"}\n\n\ndef _a_content_to_chat(content, role):\n    \"\"\"Anthropic 的 content（字串或區塊）→ OpenAI 的訊息清單（可能展開成多則：tool_result 要變成 role=tool）。\"\"\"\n    if isinstance(content, str):\n        return [{\"role\": role, \"content\": content}]\n    parts, tool_calls, tool_msgs = [], [], []\n    for b in content or []:\n        t = b.get(\"type\")\n        if t == \"text\":\n            parts.append({\"type\": \"text\", \"text\": b.get(\"text\", \"\")})\n        elif t == \"image\":\n            src = b.get(\"source\") or {}\n            if src.get(\"type\") == \"base64\":\n                parts.append({\"type\": \"image_url\", \"image_url\": {\"url\": \"data:%s;base64,%s\" % (src.get(\"media_type\", \"image/png\"), src.get(\"data\", \"\"))}})\n            elif src.get(\"type\") == \"url\":\n                parts.append({\"type\": \"image_url\", \"image_url\": {\"url\": src.get(\"url\", \"\")}})\n        elif t == \"tool_use\":\n            tool_calls.append({\"id\": b.get(\"id\") or _id(\"toolu\"), \"type\": \"function\",\n                               \"function\": {\"name\": b.get(\"name\", \"\"), \"arguments\": json.dumps(b.get(\"input\") or {}, ensure_ascii=False)}})\n        elif t == \"tool_result\":\n            tool_msgs.append({\"role\": \"tool\", \"tool_call_id\": b.get(\"tool_use_id\", \"\"), \"content\": text_of(b.get(\"content\")) or (\"（錯誤）\" if b.get(\"is_error\") else \"\")})\n        elif t in (\"thinking\", \"redacted_thinking\"):\n            continue\n    out = []\n    if parts or tool_calls:\n        msg = {\"role\": role}\n        if parts and all(p[\"type\"] == \"text\" for p in parts):\n            msg[\"content\"] = \"\".join(p[\"text\"] for p in parts)\n        else:\n            msg[\"content\"] = parts or None\n        if tool_calls:\n            msg[\"tool_calls\"] = tool_calls\n        out.append(msg)\n    return tool_msgs + out if role == \"user\" else out + tool_msgs\n\n\ndef anthropic_to_chat(model=None, messages=None, system=None, max_tokens=None, temperature=None, top_p=None, stop_sequences=None, tools=None, tool_choice=None, **kw):\n    msgs = []\n    if system:\n        msgs.append({\"role\": \"system\", \"content\": text_of(system)})\n    for m in messages or []:\n        msgs.extend(_a_content_to_chat(m.get(\"content\"), m.get(\"role\", \"user\")))\n    oa_tools = None\n    if tools:\n        oa_tools = [{\"type\": \"function\", \"function\": {\"name\": t.get(\"name\"), \"description\": t.get(\"description\", \"\"),\n                                                      \"parameters\": t.get(\"input_schema\") or {\"type\": \"object\", \"properties\": {}}}} for t in tools if t.get(\"name\")]\n    tc = None\n    if isinstance(tool_choice, dict):\n        k = tool_choice.get(\"type\")\n        tc = \"auto\" if k == \"auto\" else (\"required\" if k == \"any\" else ({\"type\": \"function\", \"function\": {\"name\": tool_choice.get(\"name\")}} if k == \"tool\" else (\"none\" if k == \"none\" else None)))\n    return chat_request(model=model, messages=msgs, temperature=temperature, top_p=top_p, max_tokens=max_tokens, stop=stop_sequences or None, tools=oa_tools, tool_choice=tc)\n\n\ndef chat_to_anthropic(resp, requested=None):\n    ch = (resp.get(\"choices\") or [{}])[0]\n    msg = ch.get(\"message\") or {}\n    content = []\n    text = text_of(msg.get(\"content\"))\n    if text or not msg.get(\"tool_calls\"):\n        content.append({\"type\": \"text\", \"text\": text})\n    for tc in msg.get(\"tool_calls\") or []:\n        fn = tc.get(\"function\") or {}\n        try:\n            inp = json.loads(fn.get(\"arguments\") or \"{}\")\n        except ValueError:\n            inp = {\"_raw\": fn.get(\"arguments\")}\n        content.append({\"type\": \"tool_use\", \"id\": tc.get(\"id\") or _id(\"toolu\"), \"name\": fn.get(\"name\", \"\"), \"input\": inp})\n    u = resp.get(\"usage\") or {}\n    return {\"id\": _id(\"msg\"), \"type\": \"message\", \"role\": \"assistant\", \"model\": resp.get(\"model\") or requested or \"assistant\", \"content\": content,\n            \"stop_reason\": _STOP_MAP.get(ch.get(\"finish_reason\") or \"stop\", \"end_turn\"), \"stop_sequence\": None,\n            \"usage\": {\"input_tokens\": u.get(\"prompt_tokens\") or 0, \"output_tokens\": u.get(\"completion_tokens\") or 0}}\n\n\ndef anthropic_events(m, chunk_chars=24):\n    \"\"\"Anthropic messages 的串流事件（模擬）。\"\"\"\n    start = dict(m, content=[], stop_reason=None, usage={\"input_tokens\": m[\"usage\"][\"input_tokens\"], \"output_tokens\": 0})\n    yield {\"type\": \"message_start\", \"message\": start}\n    for i, b in enumerate(m[\"content\"]):\n        if b[\"type\"] == \"text\":\n            yield {\"type\": \"content_block_start\", \"index\": i, \"content_block\": {\"type\": \"text\", \"text\": \"\"}}\n            t = b[\"text\"]\n            for k in range(0, len(t), max(1, chunk_chars)):\n                yield {\"type\": \"content_block_delta\", \"index\": i, \"delta\": {\"type\": \"text_delta\", \"text\": t[k:k + chunk_chars]}}\n        else:\n            yield {\"type\": \"content_block_start\", \"index\": i, \"content_block\": {\"type\": \"tool_use\", \"id\": b[\"id\"], \"name\": b[\"name\"], \"input\": {}}}\n            js = json.dumps(b[\"input\"], ensure_ascii=False)\n            for k in range(0, len(js), 40):\n                yield {\"type\": \"content_block_delta\", \"index\": i, \"delta\": {\"type\": \"input_json_delta\", \"partial_json\": js[k:k + 40]}}\n        yield {\"type\": \"content_block_stop\", \"index\": i}\n    yield {\"type\": \"message_delta\", \"delta\": {\"stop_reason\": m[\"stop_reason\"], \"stop_sequence\": None}, \"usage\": {\"output_tokens\": m[\"usage\"][\"output_tokens\"]}}\n    yield {\"type\": \"message_stop\"}\n\n\n# ---------------------------------------------------------------- SSE 文字（給直接送 HTTP 的腳本用）\ndef sse(events, done=False):\n    out = []\n    for e in events:\n        name = e.get(\"type\") if isinstance(e, dict) and \"type\" in e and \"object\" not in e else None\n        out.append((\"event: %s\\n\" % name if name else \"\") + \"data: \" + json.dumps(e, ensure_ascii=False) + \"\\n\\n\")\n    if done:\n        out.append(\"data: [DONE]\\n\\n\")\n    return \"\".join(out)\n\n\n# ---------------------------------------------------------------- 嵌入（回應）格式\ndef embeddings_response(vectors, model, tokens=0):\n    return {\"object\": \"list\", \"model\": model or \"assistant-embedding\",\n            \"data\": [{\"object\": \"embedding\", \"index\": i, \"embedding\": v} for i, v in enumerate(vectors)],\n            \"usage\": {\"prompt_tokens\": tokens, \"total_tokens\": tokens}}\n","fa_net.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_net — 一般 HTTP（不是 LLM 端點）的去處，以及 http.client 的攔截。\n\n兩個去處：\n  1. 本機網址（127.0.0.1、localhost、[::1]、*.localhost、*.local）\n     助理的沙盒有 mock 伺服器（資料存在 IndexedDB 的持久儲存那一層）時，請求就接給它；\n     沒有 mock 伺服器：網頁版回「連線被拒」（Pyodide 沒有 socket，本來就連不到），桌面版照原本連真的本機伺服器。\n  2. 外部網址（只有網頁版）\n     Pyodide 沒有 socket、又有 CORS，所以改走助理既有的出口 _terminalHttpFetch：有設定 proxy／Cloudflare Worker 就經過它，\n     沒設定就直接 fetch（可能被 CORS 擋下，錯誤訊息會說明）。桌面版的外部網址照原本連網，不經過這裡。\n\nhttp.client 的 HTTPConnection／HTTPSConnection.request() 會先問 route()；有人接手就不真的連線，getresponse() 回一個標準的 HTTPResponse。\nrequests／httpx／urllib 由 fa_http 的攔截呼叫同一個 route()（先看是不是 LLM 端點，再看這裡）。\n想讓某個主機完全不被攔截：環境變數 FA_HTTP_BYPASS_HOSTS=host1,host2。\n限制：只攔 request()（urlopen、requests 的 urllib3 都是用它）；自己用 putrequest／putheader／endheaders 逐步組請求的程式不攔。\n\"\"\"\nimport base64\nimport http.client\nimport io\nimport os\nimport sys\n\nimport fa_bridge\n\n_INSTALLED = {\"done\": False}\n\n\ndef is_local_host(host):\n    h = (host or \"\").lower().strip(\"[]\")\n    return h in (\"localhost\", \"127.0.0.1\", \"::1\", \"0.0.0.0\") or h.startswith(\"127.\") or h.endswith(\".localhost\") or h.endswith(\".local\")\n\n\ndef route(method, url, headers=None, body=b\"\"):\n    \"\"\"回 (status, headers_dict, body_bytes)；不接手就回 None。連不上會丟 ConnectionError。\"\"\"\n    if not fa_bridge.ACTIVE:\n        return None\n    try:\n        from urllib.parse import urlparse\n        u = urlparse(url)\n    except Exception:\n        return None\n    if not (u.scheme or \"\").startswith(\"http\"):\n        return None\n    host = (u.hostname or \"\").lower()\n    if host in [h.strip().lower() for h in os.environ.get(\"FA_HTTP_BYPASS_HOSTS\", \"\").split(\",\") if h.strip()]:\n        return None\n    local = is_local_host(host)\n    if not local and not fa_bridge.IN_BROWSER:\n        return None\n    if isinstance(body, str):\n        body = body.encode(\"utf-8\")\n    args = {\"method\": (method or \"GET\").upper(), \"url\": url, \"headers\": {str(k): str(v) for k, v in (headers or {}).items()},\n            \"b64\": base64.b64encode(body).decode(\"ascii\") if body else \"\"}\n    if local:\n        r = fa_bridge.call(\"net.local\", args, timeout=90.0)\n        if r.get(\"found\"):\n            return _pack(r)\n        if fa_bridge.IN_BROWSER:\n            names = r.get(\"servers\") or []\n            raise ConnectionRefusedError(\"連不到 %s：網頁版沒有真的本機伺服器，也沒有開著的 mock 伺服器（沙盒的 sandbox_mock 部署過的：%s）。先用 sandbox_mock 部署一個伺服器程式再連。\" % (host, \"、\".join(names) or \"無\"))\n        return None\n    try:\n        r = fa_bridge.call(\"net.fetch\", args, timeout=180.0)\n    except fa_bridge.BridgeError as e:\n        raise ConnectionError(str(e))\n    return _pack(r)\n\n\ndef _pack(r):\n    h = {}\n    for k, v in r.get(\"headers\") or []:\n        k = str(k).lower()\n        h[k] = (h[k] + \", \" + v) if k in h and k != \"set-cookie\" else v\n    return int(r.get(\"status\") or 502), h, base64.b64decode(r.get(\"b64\") or \"\")\n\n\nclass _FakeSock(object):\n    def __init__(self, raw):\n        self._raw = raw\n\n    def makefile(self, *a, **k):\n        return io.BytesIO(self._raw)\n\n    def close(self):\n        pass\n\n\ndef _make_response(status, headers, body, reason, method):\n    lines = [\"HTTP/1.1 %d %s\" % (status, reason or http.client.responses.get(status, \"Status\"))]\n    hs = {k: v for k, v in headers.items() if k not in (\"content-length\", \"transfer-encoding\", \"connection\")}\n    for k, v in hs.items():\n        lines.append(\"%s: %s\" % (k, v))\n    lines.append(\"Content-Length: %d\" % len(body))\n    lines.append(\"Connection: close\")\n    raw = (\"\\r\\n\".join(lines) + \"\\r\\n\\r\\n\").encode(\"latin-1\", \"replace\") + (b\"\" if method == \"HEAD\" else body)\n    resp = http.client.HTTPResponse(_FakeSock(raw), method=method)\n    resp.begin()\n    return resp\n\n\ndef patch_http_client():\n    if getattr(http.client.HTTPConnection.request, \"_fa_patched\", False):\n        return\n    orig_request = http.client.HTTPConnection.request\n    orig_getresponse = http.client.HTTPConnection.getresponse\n    orig_close = http.client.HTTPConnection.close\n\n    def request(self, method, url, body=None, headers=None, *a, **kw):\n        self._fa_pending = None\n        self._fa_method = (method or \"GET\").upper()\n        if fa_bridge.ACTIVE:\n            try:\n                import fa_http\n                scheme = \"https\" if isinstance(self, http.client.HTTPSConnection) else \"http\"\n                default = 443 if scheme == \"https\" else 80\n                host = self.host if \":\" not in self.host else \"[\" + self.host + \"]\"\n                full = url if url.startswith(\"http\") else \"%s://%s%s%s\" % (scheme, host, \"\" if self.port == default else \":%d\" % self.port, url)\n                payload = body\n                if payload is not None and not isinstance(payload, (bytes, bytearray, str)):\n                    payload = payload.read() if hasattr(payload, \"read\") else b\"\".join(x if isinstance(x, bytes) else str(x).encode(\"utf-8\") for x in payload)\n                r = fa_http.route(method, full, dict(headers or {}), payload or b\"\")\n            except OSError as e:\n                self._fa_pending = e\n                return None\n            if r is not None:\n                self._fa_pending = r\n                return None\n        return orig_request(self, method, url, body, headers or {}, *a, **kw)\n\n    def getresponse(self):\n        p = getattr(self, \"_fa_pending\", None)\n        if p is None:\n            return orig_getresponse(self)\n        self._fa_pending = None\n        if isinstance(p, Exception):\n            raise p\n        status, h, payload = p[0], p[1], p[2]\n        reason = \"\"\n        return _make_response(status, h, payload, reason, getattr(self, \"_fa_method\", \"GET\"))\n\n    def close(self):\n        self._fa_pending = None\n        return orig_close(self)\n    request._fa_patched = True\n    http.client.HTTPConnection.request = request\n    http.client.HTTPConnection.getresponse = getresponse\n    http.client.HTTPConnection.close = close\n\n\ndef install():\n    if _INSTALLED[\"done\"]:\n        return\n    _INSTALLED[\"done\"] = True\n    try:\n        patch_http_client()\n    except Exception as e:\n        sys.stderr.write(\"[fa-bridge] patch http.client: %s\\n\" % e)\n","fa_run.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_run.py — Floating AI Assistant 執行技能包 Python 腳本的啟動器。\n\n用法（由助理自動改寫指令，不需要手動打）：\n    python fa_run.py --rpc <信箱資料夾> -- <腳本.py> [腳本參數…]\n    python fa_run.py --rpc <信箱資料夾> --argsfile <args.json>   （腳本路徑或參數含中文等非 ASCII 字元時用）\n\n作用：讓腳本 import 到「轉接版」的 playwright（實際呼叫助理的瀏覽器工具）與 fa_bridge，\n並把同樣的設定傳給腳本再啟動的子程序（PYTHONPATH），然後照原樣執行腳本。\n\"\"\"\nimport os\nimport runpy\nimport sys\n\n\ndef main():\n    argv = sys.argv[1:]\n    rpc = \"\"\n    if argv[:1] == [\"--rpc\"] and len(argv) >= 2:\n        rpc = argv[1]\n        argv = argv[2:]\n    if argv[:1] == [\"--argsfile\"] and len(argv) >= 2:\n        # Windows 的指令列碰到中文路徑會變成亂碼（例如 週報 → �g��），所以腳本路徑與參數改放在 UTF-8 的 JSON 檔裡傳進來\n        import json\n        with open(argv[1], \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n        argv = [data[\"script\"]] + list(data.get(\"args\", []))\n    elif argv[:1] == [\"--\"]:\n        argv = argv[1:]\n    if not argv:\n        sys.stderr.write(\"fa_run.py: 沒有指定要執行的腳本\\n\")\n        return 2\n    # Windows 主控台預設是 cp950，助理讀輸出時當 UTF-8 解碼，中文會變成亂碼（�g��）；統一輸出 UTF-8（子程序也一樣）\n    os.environ[\"PYTHONIOENCODING\"] = \"utf-8\"\n    os.environ[\"PYTHONUTF8\"] = \"1\"\n    for _s in (sys.stdout, sys.stderr):\n        try:\n            _s.reconfigure(encoding=\"utf-8\")\n        except Exception:\n            pass\n    here = os.path.dirname(os.path.abspath(__file__))\n    script = os.path.abspath(argv[0])\n    os.environ[\"FA_BRIDGE_RPC\"] = rpc\n    os.environ[\"PYTHONPATH\"] = here + os.pathsep + os.environ.get(\"PYTHONPATH\", \"\")\n    sys.path.insert(0, here)\n    sys.path.insert(1, os.path.dirname(script))  # 跟直接 python script.py 一樣，腳本所在資料夾在 sys.path 裡\n    sys.argv = [script] + argv[1:]\n    try:\n        import fa_bridge\n        fa_bridge.install_hooks()  # 直接送 HTTP 的 LLM 呼叫（OpenAI 標準與 Claude 格式）轉給助理的模型\n    except Exception as e:\n        sys.stderr.write(\"[fa-bridge] install_hooks: %s\" % e + chr(10))\n    runpy.run_path(script, run_name=\"__main__\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main() or 0)\n","fa_sim.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_sim — 助理沒有對應能力時的「回應模擬」（只用標準函式庫）。\n\nOpenAI／Claude 的 API 有些功能助理沒有對應的東西（審核、檔案、批次、微調、assistants…）。\n腳本在這些地方丟例外會讓整支腳本壞掉，所以這裡提供「結構正確、內容誠實」的模擬回應：\n  * 欄位與型別跟真的一樣，腳本的後續處理不會因為少欄位而當掉；\n  * 內容不假裝是真的：微調工作直接回報不支援、審核一律回報未違規並標示是模擬；\n  * 每次模擬都會通知助理（fa_llm.note_simulated），上層 AI 看得到「哪些呼叫是模擬的」。\n能真的做的就真的做：batches 逐筆走助理的模型、threads／runs 用助理的模型回答。\n圖片、語音、嵌入、工具呼叫不模擬——先從已設定的 LLM Model 找有支援的，所有 Model 都不支援才丟 NotSupported。\n\"\"\"\nimport base64\nimport io\nimport json\nimport re\nimport struct\nimport time\nimport uuid\nimport zlib\n\nimport fa_llm\n\n_STORE = {\"files\": {}, \"batches\": {}, \"threads\": {}, \"vector_stores\": {}, \"assistants\": {}, \"jobs\": {}}\n\n\ndef _id(p):\n    return \"%s_%s\" % (p, uuid.uuid4().hex[:20])\n\n\ndef _now():\n    return int(time.time())\n\n\n# 圖片、語音、嵌入、工具呼叫「不」在這裡模擬：它們要先從助理已設定的 LLM Model 清單裡找有這個能力的 Model（fa_llm.upstream），\n# 所有 Model 都不支援才丟 NotSupported，不會回傳假的結果。\nclass SimBytes(object):\n    \"\"\"二進位內容的回應（有 .content、.read()、.iter_bytes()、.stream_to_file()）。語音合成等真的由 Model 回傳的二進位用這個包起來。\"\"\"\n\n    def __init__(self, data, content_type=None):\n        self.content = data\n        self.content_type = content_type\n\n    def read(self):\n        return self.content\n\n    def iter_bytes(self, chunk_size=1024):\n        for i in range(0, len(self.content), chunk_size):\n            yield self.content[i:i + chunk_size]\n\n    def stream_to_file(self, path):\n        with open(path, \"wb\") as f:\n            f.write(self.content)\n\n    write_to_file = stream_to_file\n\n    @property\n    def text(self):\n        return self.content.decode(\"utf-8\", \"replace\")\n\n\ndef _mark(d, api):\n    d[\"fa_simulated\"] = True\n    fa_llm.note_simulated(api)\n    return d\n\n\n# ---------------------------------------------------------------- 審核\n_CATS = [\"hate\", \"hate/threatening\", \"harassment\", \"harassment/threatening\", \"self-harm\", \"self-harm/intent\", \"self-harm/instructions\",\n         \"sexual\", \"sexual/minors\", \"violence\", \"violence/graphic\", \"illicit\", \"illicit/violent\"]\n\n\ndef moderation(input=None, model=None, **kw):\n    items = input if isinstance(input, list) else [input]\n    res = [{\"flagged\": False, \"categories\": {c: False for c in _CATS}, \"category_scores\": {c: 0.0 for c in _CATS}} for _ in items]\n    return _mark({\"id\": _id(\"modr\"), \"model\": model or \"omni-moderation-latest\", \"results\": res}, \"moderations\")\n\n\n# ---------------------------------------------------------------- 模型\ndef models(current):\n    m = {\"id\": current or \"assistant\", \"object\": \"model\", \"created\": _now(), \"owned_by\": \"floating-assistant\"}\n    return {\"object\": \"list\", \"data\": [m]}, m\n\n\n# ---------------------------------------------------------------- 檔案（記憶體內）\ndef file_create(file=None, purpose=\"assistants\", **kw):\n    data = b\"\"\n    name = \"file\"\n    if isinstance(file, tuple):\n        name = file[0]\n        data = file[1] if len(file) > 1 else b\"\"\n        data = data.read() if hasattr(data, \"read\") else data\n    elif hasattr(file, \"read\"):\n        data = file.read()\n        name = getattr(file, \"name\", name)\n    elif isinstance(file, (bytes, str)):\n        data = file if isinstance(file, bytes) else file.encode(\"utf-8\")\n    elif isinstance(file, str):\n        data = open(file, \"rb\").read()\n        name = file\n    if isinstance(data, str):\n        data = data.encode(\"utf-8\")\n    fid = _id(\"file\")\n    meta = {\"id\": fid, \"object\": \"file\", \"bytes\": len(data), \"created_at\": _now(), \"filename\": str(name).split(\"/\")[-1].split(chr(92))[-1], \"purpose\": purpose, \"status\": \"processed\"}\n    _STORE[\"files\"][fid] = (meta, data)\n    return _mark(dict(meta), \"files.create\")\n\n\ndef file_get(fid):\n    if fid not in _STORE[\"files\"]:\n        raise KeyError(fid)\n    return _STORE[\"files\"][fid]\n\n\ndef file_list():\n    return {\"object\": \"list\", \"data\": [m for m, _ in _STORE[\"files\"].values()]}\n\n\ndef file_delete(fid):\n    _STORE[\"files\"].pop(fid, None)\n    return {\"id\": fid, \"object\": \"file\", \"deleted\": True}\n\n\n# ---------------------------------------------------------------- 批次：真的逐筆走助理的模型\ndef batch_create(input_file_id=None, endpoint=\"/v1/chat/completions\", completion_window=\"24h\", metadata=None, **kw):\n    meta, data = file_get(input_file_id)\n    outs, errs, total = [], [], 0\n    for line in data.decode(\"utf-8\", \"replace\").splitlines():\n        line = line.strip()\n        if not line:\n            continue\n        total += 1\n        try:\n            item = json.loads(line)\n            body = item.get(\"body\") or {}\n            if \"messages\" in body:\n                resp = fa_llm.complete(fa_llm.chat_request(**body))\n            else:\n                raise ValueError(\"只支援 chat/completions 的批次\")\n            outs.append({\"id\": _id(\"batch_req\"), \"custom_id\": item.get(\"custom_id\"), \"response\": {\"status_code\": 200, \"request_id\": _id(\"req\"), \"body\": resp}, \"error\": None})\n        except Exception as e:\n            errs.append({\"id\": _id(\"batch_req\"), \"custom_id\": (item or {}).get(\"custom_id\") if isinstance(locals().get(\"item\"), dict) else None,\n                         \"response\": None, \"error\": {\"code\": \"failed\", \"message\": str(e)[:300]}})\n    ofid = errfid = None\n    if outs:\n        ofid = file_create((\"batch_output.jsonl\", \"\\n\".join(json.dumps(o, ensure_ascii=False) for o in outs).encode(\"utf-8\")), purpose=\"batch_output\")[\"id\"]\n    if errs:\n        errfid = file_create((\"batch_errors.jsonl\", \"\\n\".join(json.dumps(o, ensure_ascii=False) for o in errs).encode(\"utf-8\")), purpose=\"batch_output\")[\"id\"]\n    bid = _id(\"batch\")\n    b = {\"id\": bid, \"object\": \"batch\", \"endpoint\": endpoint, \"input_file_id\": input_file_id, \"completion_window\": completion_window, \"status\": \"completed\",\n         \"output_file_id\": ofid, \"error_file_id\": errfid, \"created_at\": _now(), \"completed_at\": _now(),\n         \"request_counts\": {\"total\": total, \"completed\": len(outs), \"failed\": len(errs)}, \"metadata\": metadata}\n    _STORE[\"batches\"][bid] = b\n    return b\n\n\ndef batch_get(bid):\n    if bid not in _STORE[\"batches\"]:\n        raise KeyError(bid)\n    return _STORE[\"batches\"][bid]\n\n\n# ---------------------------------------------------------------- 微調：誠實回報不支援\ndef finetune_create(model=None, training_file=None, **kw):\n    jid = _id(\"ftjob\")\n    j = {\"id\": jid, \"object\": \"fine_tuning.job\", \"model\": model, \"training_file\": training_file, \"created_at\": _now(), \"status\": \"failed\", \"fine_tuned_model\": None,\n         \"error\": {\"code\": \"not_supported\", \"message\": \"AI 助理的轉接層不支援微調（沒有可訓練的模型）。這是模擬回應。\", \"param\": None}}\n    _STORE[\"jobs\"][jid] = j\n    return _mark(dict(j), \"fine_tuning.jobs.create\")\n\n\n# ---------------------------------------------------------------- threads／runs（Assistants，最小版：用助理的模型回答）\ndef thread_create(messages=None, **kw):\n    tid = _id(\"thread\")\n    t = {\"id\": tid, \"object\": \"thread\", \"created_at\": _now(), \"metadata\": kw.get(\"metadata\") or {}}\n    _STORE[\"threads\"][tid] = {\"meta\": t, \"messages\": []}\n    for m in messages or []:\n        message_create(tid, role=m.get(\"role\", \"user\"), content=m.get(\"content\", \"\"))\n    return _mark(dict(t), \"beta.threads.create\")\n\n\ndef message_create(thread_id, role=\"user\", content=\"\", **kw):\n    th = _STORE[\"threads\"].get(thread_id)\n    if th is None:\n        raise KeyError(thread_id)\n    msg = {\"id\": _id(\"msg\"), \"object\": \"thread.message\", \"created_at\": _now(), \"thread_id\": thread_id, \"role\": role,\n           \"content\": [{\"type\": \"text\", \"text\": {\"value\": fa_llm.text_of(content), \"annotations\": []}}], \"assistant_id\": kw.get(\"assistant_id\"), \"run_id\": kw.get(\"run_id\")}\n    th[\"messages\"].append(msg)\n    return msg\n\n\ndef messages_list(thread_id, order=\"desc\", limit=20):\n    th = _STORE[\"threads\"].get(thread_id)\n    if th is None:\n        raise KeyError(thread_id)\n    msgs = list(th[\"messages\"])\n    if order == \"desc\":\n        msgs.reverse()\n    return {\"object\": \"list\", \"data\": msgs[:int(limit or 20)], \"has_more\": False}\n\n\ndef run_create(thread_id, assistant_id=None, instructions=None, **kw):\n    th = _STORE[\"threads\"].get(thread_id)\n    if th is None:\n        raise KeyError(thread_id)\n    asst = _STORE[\"assistants\"].get(assistant_id) or {}\n    msgs = []\n    sysm = instructions or asst.get(\"instructions\")\n    if sysm:\n        msgs.append({\"role\": \"system\", \"content\": sysm})\n    for m in th[\"messages\"]:\n        msgs.append({\"role\": m[\"role\"], \"content\": m[\"content\"][0][\"text\"][\"value\"]})\n    rid = _id(\"run\")\n    try:\n        resp = fa_llm.complete(fa_llm.chat_request(messages=msgs))\n        text = fa_llm.text_of(((resp.get(\"choices\") or [{}])[0].get(\"message\") or {}).get(\"content\"))\n        message_create(thread_id, role=\"assistant\", content=text, assistant_id=assistant_id, run_id=rid)\n        status, err = \"completed\", None\n    except Exception as e:\n        status, err = \"failed\", {\"code\": \"server_error\", \"message\": str(e)[:300]}\n    return {\"id\": rid, \"object\": \"thread.run\", \"created_at\": _now(), \"thread_id\": thread_id, \"assistant_id\": assistant_id, \"status\": status, \"last_error\": err,\n            \"completed_at\": _now() if status == \"completed\" else None, \"model\": asst.get(\"model\") or \"assistant\"}\n\n\ndef assistant_create(**kw):\n    aid = _id(\"asst\")\n    a = {\"id\": aid, \"object\": \"assistant\", \"created_at\": _now(), \"name\": kw.get(\"name\"), \"description\": kw.get(\"description\"), \"model\": kw.get(\"model\") or \"assistant\",\n         \"instructions\": kw.get(\"instructions\"), \"tools\": kw.get(\"tools\") or [], \"metadata\": kw.get(\"metadata\") or {}}\n    _STORE[\"assistants\"][aid] = a\n    return _mark(dict(a), \"beta.assistants.create\")\n\n\ndef vector_store_create(name=None, **kw):\n    vid = _id(\"vs\")\n    v = {\"id\": vid, \"object\": \"vector_store\", \"created_at\": _now(), \"name\": name, \"status\": \"completed\", \"file_counts\": {\"in_progress\": 0, \"completed\": 0, \"failed\": 0, \"cancelled\": 0, \"total\": 0}}\n    _STORE[\"vector_stores\"][vid] = v\n    return _mark(dict(v), \"vector_stores.create\")\n","fa_ws.py":"# -*- coding: utf-8 -*-\n\"\"\"\nfa_ws — Python 的 WebSocket 用戶端接到沙盒 mock 伺服器（跟 fa_net 的 HTTP 同一層，支援 websocket-client 與 websockets）。\n\n本機網址（127.0.0.1、localhost、[::1]、*.localhost、*.local）有 mock 伺服器就接過去；\n沒有：網頁版丟 ConnectionRefusedError（Pyodide 沒有 socket），桌面版照原本連真的本機伺服器。\n外部網址：網頁版丟 ConnectionError（沒有可用的 WebSocket 出口），桌面版照原本連網。\n\n支援：\n  websocket-client：websocket.create_connection()（send／send_binary／recv／recv_data／settimeout／close）、WebSocketApp.run_forever()（on_open／on_message／on_error／on_close、send、close）\n  websockets：websockets.sync.client.connect()、websockets.connect()／websockets.asyncio.client.connect()（async with／await／async for、send／recv／close）\n模組在轉接安裝之後才被 import 也會補上（見 fa_http 的 import 攔截）。收訊息是短輪詢（每次最多等 250 毫秒），非同步程式同時收送不會互相卡住。\n\"\"\"\nimport base64\nimport sys\nimport time\n\nimport fa_bridge\nimport fa_net\n\n\nclass Closed(Exception):\n    def __init__(self, code=1005, reason=\"\"):\n        Exception.__init__(self, \"連線已關閉（%s %s）\" % (code, reason))\n        self.code = code\n        self.reason = reason\n\n\ndef _applies(url):\n    \"\"\"要接手就回 True；不接手回 False（桌面版放行）；網頁版沒出口就丟錯。\"\"\"\n    if not fa_bridge.ACTIVE:\n        return False\n    try:\n        from urllib.parse import urlparse\n        host = (urlparse(url).hostname or \"\").lower()\n    except Exception:\n        return False\n    if fa_net.is_local_host(host):\n        return True\n    if fa_bridge.IN_BROWSER:\n        raise ConnectionError(\"網頁版連不到外部 WebSocket（%s）：沒有可用的 WebSocket 出口；本機網址（127.0.0.1／localhost／*.local）可以連沙盒的 mock 伺服器。\" % host)\n    return False\n\n\ndef _headers(h):\n    out = {}\n    if isinstance(h, dict):\n        out = {str(k): str(v) for k, v in h.items()}\n    elif h:\n        for x in h:\n            if isinstance(x, (tuple, list)) and len(x) == 2:\n                out[str(x[0])] = str(x[1])\n            elif isinstance(x, str) and \":\" in x:\n                k, _, v = x.partition(\":\")\n                out[k.strip()] = v.strip()\n    return out\n\n\ndef _opened(r, url):\n    if not r.get(\"found\"):\n        if fa_bridge.IN_BROWSER:\n            raise ConnectionRefusedError(\"連不到 %s：網頁版沒有真的本機伺服器，也沒有開著的 mock 伺服器（沙盒部署過的：%s）。先用 sandbox_mock 部署一個有 WebSocket 的伺服器程式。\" % (url, \"、\".join(r.get(\"servers\") or []) or \"無\"))\n        return None\n    if not r.get(\"ok\"):\n        raise ConnectionError(\"WebSocket 連線失敗：%s\" % r.get(\"error\"))\n    return _Sock(r[\"id\"])\n\n\ndef open_mock(url, headers=None):\n    \"\"\"接手就回 _Sock；桌面版沒有 mock 伺服器回 None（照原本連）。\"\"\"\n    if not _applies(url):\n        return None\n    return _opened(fa_bridge.call(\"ws.open\", {\"url\": url, \"headers\": _headers(headers)}, timeout=30.0), url)\n\n\nasync def aopen_mock(url, headers=None):\n    if not _applies(url):\n        return None\n    return _opened(await fa_bridge.acall(\"ws.open\", {\"url\": url, \"headers\": _headers(headers)}, timeout=30.0), url)\n\n\ndef _msg(r):\n    if r.get(\"text\") is not None:\n        return r[\"text\"]\n    if r.get(\"binary\"):\n        return base64.b64decode(r.get(\"b64\") or \"\")\n    return None\n\n\nclass _Sock(object):\n    def __init__(self, sid):\n        self.id = sid\n        self.closed = None\n\n    def _send_args(self, data):\n        if isinstance(data, (bytes, bytearray, memoryview)):\n            return {\"id\": self.id, \"binary\": True, \"b64\": base64.b64encode(bytes(data)).decode(\"ascii\")}\n        return {\"id\": self.id, \"text\": str(data)}\n\n    def _check(self, r):\n        if r.get(\"closed\"):\n            self.closed = r[\"closed\"]\n            raise Closed(self.closed.get(\"code\"), self.closed.get(\"reason\"))\n\n    def send(self, data):\n        self._check(fa_bridge.call(\"ws.send\", self._send_args(data), timeout=30.0) or {})\n\n    async def asend(self, data):\n        self._check(await fa_bridge.acall(\"ws.send\", self._send_args(data), timeout=30.0) or {})\n\n    def recv(self, timeout=None):\n        end = None if timeout is None else time.time() + timeout\n        while True:\n            if self.closed:\n                raise Closed(self.closed.get(\"code\"), self.closed.get(\"reason\"))\n            r = fa_bridge.call(\"ws.recv\", {\"id\": self.id, \"wait_ms\": 250}, timeout=30.0) or {}\n            self._check(r)\n            m = _msg(r)\n            if m is not None:\n                return m\n            if end is not None and time.time() >= end:\n                raise TimeoutError(\"等不到 WebSocket 訊息\")\n\n    async def arecv(self, timeout=None):\n        import asyncio\n        end = None if timeout is None else time.time() + timeout\n        while True:\n            if self.closed:\n                raise Closed(self.closed.get(\"code\"), self.closed.get(\"reason\"))\n            r = await fa_bridge.acall(\"ws.recv\", {\"id\": self.id, \"wait_ms\": 250}, timeout=30.0) or {}\n            self._check(r)\n            m = _msg(r)\n            if m is not None:\n                return m\n            if end is not None and time.time() >= end:\n                raise TimeoutError(\"等不到 WebSocket 訊息\")\n            await asyncio.sleep(0)\n\n    def close(self, code=1000, reason=\"\"):\n        if self.closed is None:\n            try:\n                fa_bridge.call(\"ws.close\", {\"id\": self.id, \"code\": code, \"reason\": reason}, timeout=15.0)\n            except Exception:\n                pass\n            self.closed = {\"code\": code, \"reason\": reason}\n\n    async def aclose(self, code=1000, reason=\"\"):\n        if self.closed is None:\n            try:\n                await fa_bridge.acall(\"ws.close\", {\"id\": self.id, \"code\": code, \"reason\": reason}, timeout=15.0)\n            except Exception:\n                pass\n            self.closed = {\"code\": code, \"reason\": reason}\n\n\n# ---------------------------------------------------------------- websocket-client\ndef patch_websocket_client():\n    import websocket\n    if getattr(websocket.create_connection, \"_fa_patched\", False):\n        return\n    exc_closed = getattr(websocket, \"WebSocketConnectionClosedException\", Exception)\n    exc_timeout = getattr(websocket, \"WebSocketTimeoutException\", TimeoutError)\n\n    class _WSC(object):\n        def __init__(self, sock):\n            self._s = sock\n            self.timeout = None\n            self.status = 101\n            self.headers = {}\n\n        @property\n        def connected(self):\n            return self._s.closed is None\n\n        def send(self, payload, opcode=1):\n            self._s.send(payload.encode(\"utf-8\") if opcode == 2 and isinstance(payload, str) else payload)\n            return len(payload)\n\n        def send_text(self, s):\n            return self.send(s)\n\n        def send_binary(self, b):\n            self._s.send(bytes(b))\n            return len(b)\n\n        def recv(self):\n            try:\n                return self._s.recv(self.timeout)\n            except Closed:\n                raise exc_closed(\"Connection is already closed.\")\n            except TimeoutError:\n                raise exc_timeout(\"timed out\")\n\n        def recv_data(self, control_frame=False):\n            m = self.recv()\n            return (2, m) if isinstance(m, bytes) else (1, m.encode(\"utf-8\"))\n\n        def settimeout(self, t):\n            self.timeout = t\n\n        def gettimeout(self):\n            return self.timeout\n\n        def getstatus(self):\n            return 101\n\n        def getheaders(self):\n            return {}\n\n        def close(self, status=1000, reason=b\"\", timeout=3):\n            self._s.close(status, reason.decode(\"utf-8\", \"replace\") if isinstance(reason, bytes) else str(reason))\n\n        shutdown = close\n\n        def __enter__(self):\n            return self\n\n        def __exit__(self, *a):\n            self.close()\n\n        def __iter__(self):\n            while self.connected:\n                try:\n                    yield self.recv()\n                except exc_closed:\n                    return\n\n    orig_create = websocket.create_connection\n\n    def create_connection(url, timeout=None, **options):\n        s = open_mock(url, options.get(\"header\"))\n        if s is None:\n            return orig_create(url, timeout=timeout, **options)\n        c = _WSC(s)\n        c.timeout = timeout\n        return c\n    create_connection._fa_patched = True\n    websocket.create_connection = create_connection\n\n    App = getattr(websocket, \"WebSocketApp\", None)\n    if App is None:\n        return\n    orig_run, orig_send, orig_close = App.run_forever, App.send, App.close\n\n    def run_forever(self, *a, **kw):\n        s = None\n        try:\n            s = open_mock(self.url, getattr(self, \"header\", None))\n        except Exception as e:\n            self._fa_call(\"on_error\", e)\n            return False\n        if s is None:\n            return orig_run(self, *a, **kw)\n        self._fa_sock = s\n        self.keep_running = True\n        self._fa_call(\"on_open\")\n        try:\n            while self.keep_running and s.closed is None:\n                try:\n                    m = s.recv(0.25)\n                except TimeoutError:\n                    continue\n                except Closed:\n                    break\n                self._fa_call(\"on_message\", m)\n        except Exception as e:\n            self._fa_call(\"on_error\", e)\n        finally:\n            c = s.closed or {\"code\": 1005, \"reason\": \"\"}\n            s.close()\n            self.keep_running = False\n            self._fa_call(\"on_close\", c.get(\"code\"), c.get(\"reason\"))\n        return False\n\n    def _fa_call(self, name, *args):\n        cb = getattr(self, name, None)\n        if cb:\n            cb(self, *args)\n\n    def send(self, data, opcode=1):\n        s = getattr(self, \"_fa_sock\", None)\n        if s is None:\n            return orig_send(self, data, opcode)\n        s.send(data.encode(\"utf-8\") if opcode == 2 and isinstance(data, str) else data)\n\n    def close(self, **kw):\n        s = getattr(self, \"_fa_sock\", None)\n        if s is None:\n            return orig_close(self, **kw)\n        self.keep_running = False\n        s.close(kw.get(\"status\", 1000), \"\")\n    App.run_forever, App.send, App.close, App._fa_call = run_forever, send, close, _fa_call\n\n\n# ---------------------------------------------------------------- websockets\ndef _closed_exc():\n    try:\n        from websockets.exceptions import ConnectionClosedOK\n        return ConnectionClosedOK\n    except Exception:\n        return Closed\n\n\ndef _mk_closed(c):\n    cls = _closed_exc()\n    try:\n        return cls(None, None)\n    except Exception:\n        return cls(c.code, c.reason)\n\n\nclass _WSS(object):\n    \"\"\"websockets.sync.client 的連線。\"\"\"\n\n    def __init__(self, sock):\n        self._s = sock\n\n    def send(self, message, text=None):\n        try:\n            self._s.send(message)\n        except Closed as c:\n            raise _mk_closed(c)\n\n    def recv(self, timeout=None, decode=None):\n        try:\n            m = self._s.recv(timeout)\n        except Closed as c:\n            raise _mk_closed(c)\n        if decode is True and isinstance(m, bytes):\n            return m.decode(\"utf-8\")\n        if decode is False and isinstance(m, str):\n            return m.encode(\"utf-8\")\n        return m\n\n    def close(self, code=1000, reason=\"\"):\n        self._s.close(code, reason)\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        self.close()\n\n    def __iter__(self):\n        while True:\n            try:\n                yield self.recv()\n            except _closed_exc():\n                return\n\n    @property\n    def open(self):\n        return self._s.closed is None\n\n    @property\n    def closed(self):\n        return self._s.closed is not None\n\n\nclass _AWSS(object):\n    \"\"\"websockets 非同步連線。\"\"\"\n\n    def __init__(self, sock):\n        self._s = sock\n\n    async def send(self, message, text=None):\n        try:\n            await self._s.asend(message)\n        except Closed as c:\n            raise _mk_closed(c)\n\n    async def recv(self, decode=None):\n        try:\n            m = await self._s.arecv()\n        except Closed as c:\n            raise _mk_closed(c)\n        if decode is True and isinstance(m, bytes):\n            return m.decode(\"utf-8\")\n        if decode is False and isinstance(m, str):\n            return m.encode(\"utf-8\")\n        return m\n\n    async def close(self, code=1000, reason=\"\"):\n        await self._s.aclose(code, reason)\n\n    async def wait_closed(self):\n        return None\n\n    def __aiter__(self):\n        return self\n\n    async def __anext__(self):\n        try:\n            return await self.recv()\n        except _closed_exc():\n            raise StopAsyncIteration\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *a):\n        await self.close()\n\n    @property\n    def open(self):\n        return self._s.closed is None\n\n    @property\n    def closed(self):\n        return self._s.closed is not None\n\n\nclass _AConnect(object):\n    def __init__(self, orig, uri, a, kw):\n        self._orig, self._uri, self._a, self._kw = orig, uri, a, kw\n        self._real = None\n\n    async def _open(self):\n        s = await aopen_mock(self._uri, self._kw.get(\"additional_headers\") or self._kw.get(\"extra_headers\"))\n        if s is not None:\n            return _AWSS(s)\n        self._real = self._orig(self._uri, *self._a, **self._kw)\n        return await self._real\n\n    def __await__(self):\n        return self._open().__await__()\n\n    async def __aenter__(self):\n        self._conn = await self._open()\n        if self._real is not None:\n            return self._conn\n        return self._conn\n\n    async def __aexit__(self, *exc):\n        if self._real is not None and hasattr(self._real, \"__aexit__\"):\n            return await self._real.__aexit__(*exc)\n        await self._conn.close()\n\n\ndef patch_websockets():\n    import websockets\n    if getattr(websockets, \"_fa_ws_patched\", False):\n        return\n    websockets._fa_ws_patched = True\n    try:\n        import websockets.sync.client as sc\n        orig_sc = sc.connect\n\n        def sync_connect(uri, *a, **kw):\n            s = open_mock(uri, kw.get(\"additional_headers\"))\n            return _WSS(s) if s is not None else orig_sc(uri, *a, **kw)\n        sc.connect = sync_connect\n    except Exception:\n        pass\n    for modname in (\"websockets.asyncio.client\", \"websockets.client\", \"websockets.legacy.client\"):\n        try:\n            mod = __import__(modname, fromlist=[\"connect\"])\n            orig = getattr(mod, \"connect\", None)\n            if orig is None or getattr(orig, \"_fa_patched\", False):\n                continue\n\n            def make(o):\n                def connect(uri, *a, **kw):\n                    return _AConnect(o, uri, a, kw)\n                connect._fa_patched = True\n                return connect\n            mod.connect = make(orig)\n        except Exception:\n            continue\n    try:\n        orig_top = websockets.connect\n        if not getattr(orig_top, \"_fa_patched\", False):\n            def top(uri, *a, **kw):\n                return _AConnect(orig_top, uri, a, kw)\n            top._fa_patched = True\n            websockets.connect = top\n    except Exception:\n        pass\n","openai/__init__.py":"# -*- coding: utf-8 -*-\n\"\"\"\nopenai 的「轉接版」：Floating AI Assistant 在執行技能包的 Python 腳本時提供。\n\n腳本照原本的寫法（同步或 async 都可以）：\n    from openai import OpenAI, AsyncOpenAI\n    client = OpenAI(base_url=..., api_key=...)\n    client.chat.completions.create(model=..., messages=[...], tools=[...], stream=True)\n    client.responses.create(...); client.embeddings.create(...); client.images.generate(...); client.audio.transcriptions.create(...)\n\n但實際上不會連腳本設定的 base_url／金鑰，而是用 AI 助理「已設定的 LLM Model 清單」裡的 Model（腳本自己的 base_url、api_key、model 都忽略）：\n  * chat／responses／completions：用目前的 Model；有 tools 就挑支援工具呼叫的 Model，有圖片就挑支援讀圖的 Model（依序試）。\n  * embeddings、images、audio：不直接當不支援——從清單裡找有這個能力的 Model（依序試），所有 Model 都不支援才丟 openai.NotSupportedError。\n  * 串流（stream=True）：上游整段回來後分段送出（行為跟真的串流一樣，只是沒有逐字延遲）。\n  * moderations、files、batches、threads／runs、fine_tuning 等助理沒有對應的東西：用 fa_sim 的模擬回應（欄位正確、內容誠實、並通知助理「這是模擬的」）。\n\"\"\"\nimport json\nimport re\n\nimport fa_bridge\nimport fa_llm\nimport fa_sim\n\n__version__ = \"1.99.0+fa-bridge\"\n\n\n# ---------------------------------------------------------------- 錯誤（跟真的 openai 套件同名同繼承）\nclass OpenAIError(Exception):\n    pass\n\n\nclass APIError(OpenAIError):\n    def __init__(self, message=\"\", request=None, body=None, **kw):\n        super(APIError, self).__init__(message)\n        self.message = message\n        self.request = request\n        self.body = body\n        self.code = (body or {}).get(\"code\") if isinstance(body, dict) else None\n        self.param = None\n        self.type = None\n\n\nclass APIStatusError(APIError):\n    status_code = 500\n\n    def __init__(self, message=\"\", response=None, body=None, status_code=None, **kw):\n        super(APIStatusError, self).__init__(message, body=body)\n        self.response = response\n        if status_code:\n            self.status_code = status_code\n        self.request_id = None\n\n\nclass APIConnectionError(APIError):\n    pass\n\n\nclass APITimeoutError(APIConnectionError):\n    pass\n\n\nclass BadRequestError(APIStatusError):\n    status_code = 400\n\n\nclass AuthenticationError(APIStatusError):\n    status_code = 401\n\n\nclass PermissionDeniedError(APIStatusError):\n    status_code = 403\n\n\nclass NotFoundError(APIStatusError):\n    status_code = 404\n\n\nclass ConflictError(APIStatusError):\n    status_code = 409\n\n\nclass UnprocessableEntityError(APIStatusError):\n    status_code = 422\n\n\nclass RateLimitError(APIStatusError):\n    status_code = 429\n\n\nclass InternalServerError(APIStatusError):\n    status_code = 500\n\n\nclass NotSupportedError(APIStatusError, NotImplementedError):\n    \"\"\"助理已設定的所有 LLM Model 都沒有這個能力。\"\"\"\n    status_code = 501\n\n\n_STATUS_CLS = {400: BadRequestError, 401: AuthenticationError, 403: PermissionDeniedError, 404: NotFoundError, 409: ConflictError, 422: UnprocessableEntityError, 429: RateLimitError}\n\n\ndef _translate(e):\n    \"\"\"把橋接的錯誤轉成 openai 套件的錯誤型別（腳本的 except 會照原本的寫法接得到）。\"\"\"\n    if isinstance(e, fa_bridge.NotSupported):\n        return NotSupportedError(str(e) or \"沒有任何已設定的 LLM Model 支援這個功能\")\n    msg = str(e)\n    m = re.search(r\"API錯誤\\((\\d{3})\\)\", msg)\n    if m:\n        code = int(m.group(1))\n        cls = _STATUS_CLS.get(code) or (InternalServerError if code >= 500 else APIStatusError)\n        return cls(msg, status_code=code)\n    if \"逾時\" in msg:\n        return APITimeoutError(msg)\n    return APIConnectionError(msg)\n\n\n# ---------------------------------------------------------------- 物件\nclass _Obj(object):\n    \"\"\"dict 包成可以用屬性存取的物件（resp.choices[0].message.content），也可以用 resp[\"choices\"]。\"\"\"\n\n    def __init__(self, d):\n        self.__dict__[\"_d\"] = d\n\n    def __getattr__(self, k):\n        if k.startswith(\"__\"):\n            raise AttributeError(k)\n        v = self.__dict__[\"_d\"].get(k)\n        return _wrap(v)\n\n    def __getitem__(self, k):\n        return _wrap(self.__dict__[\"_d\"][k])\n\n    def __contains__(self, k):\n        return k in self.__dict__[\"_d\"]\n\n    def get(self, k, default=None):\n        return _wrap(self.__dict__[\"_d\"].get(k, default))\n\n    def keys(self):\n        return self.__dict__[\"_d\"].keys()\n\n    def to_dict(self, **kw):\n        return self.__dict__[\"_d\"]\n\n    model_dump = to_dict\n\n    def to_json(self, **kw):\n        return json.dumps(self.__dict__[\"_d\"], ensure_ascii=False)\n\n    model_dump_json = to_json\n\n    def __repr__(self):\n        return \"<openai.%s %r>\" % (self.__dict__[\"_d\"].get(\"object\", \"obj\"), self.__dict__[\"_d\"])\n\n\ndef _wrap(v):\n    if isinstance(v, dict):\n        return _Obj(v)\n    if isinstance(v, list):\n        return [_wrap(x) for x in v]\n    return v\n\n\nclass Stream(object):\n    \"\"\"串流回應（同步）：for chunk in stream:。\"\"\"\n\n    def __init__(self, gen):\n        self._gen = gen\n        self.response = None\n\n    def __iter__(self):\n        return self\n\n    def __next__(self):\n        return _wrap(next(self._gen))\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        return False\n\n    def close(self):\n        pass\n\n\nclass AsyncStream(object):\n    def __init__(self, gen):\n        self._gen = gen\n\n    def __aiter__(self):\n        return self\n\n    async def __anext__(self):\n        try:\n            return _wrap(next(self._gen))\n        except StopIteration:\n            raise StopAsyncIteration\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *a):\n        return False\n\n    async def close(self):\n        pass\n\n\nclass _Raw(object):\n    \"\"\"with_raw_response 的結果：.parse() 取回物件，.headers／.http_response 給個樣子。\"\"\"\n\n    def __init__(self, obj):\n        self._obj = obj\n        self.headers = {\"x-fa-bridge\": \"1\"}\n        self.status_code = 200\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        return False\n\n    def parse(self):\n        return self._obj\n\n    def __getattr__(self, k):\n        return getattr(self._obj, k)\n\n\n# ---------------------------------------------------------------- 執行：每個操作寫成 generator，yield 請求、收回結果，同步與 async 共用\ndef _drive(gen):\n    try:\n        req = next(gen)\n        while True:\n            try:\n                res = _do(req)\n            except Exception as e:\n                req = gen.throw(_translate(e))\n                continue\n            req = gen.send(res)\n    except StopIteration as stop:\n        return stop.value\n\n\nasync def _adrive(gen):\n    try:\n        req = next(gen)\n        while True:\n            try:\n                res = await _ado(req)\n            except Exception as e:\n                req = gen.throw(_translate(e))\n                continue\n            req = gen.send(res)\n    except StopIteration as stop:\n        return stop.value\n\n\ndef _do(req):\n    k = req[0]\n    if k == \"complete\":\n        return fa_llm.complete(req[1])\n    if k == \"upstream\":\n        return fa_llm.upstream(**req[1])\n    raise ValueError(k)\n\n\nasync def _ado(req):\n    k = req[0]\n    if k == \"complete\":\n        return await fa_llm.acomplete(req[1])\n    if k == \"upstream\":\n        return await fa_llm.aupstream(**req[1])\n    raise ValueError(k)\n\n\ndef _model(r, requested):\n    return (r or {}).get(\"model\") or requested or \"assistant\"\n\n\n# ---------------------------------------------------------------- 各 API 的操作（generator）\ndef _op_chat(model=None, messages=None, stream=False, stream_options=None, **kw):\n    req = fa_llm.chat_request(model, messages, **kw)\n    r = yield (\"complete\", req)\n    r = dict(r or {})\n    r[\"model\"] = _model(r, model)\n    if stream:\n        gen = fa_llm.chat_chunks(r, include_usage=bool((stream_options or {}).get(\"include_usage\")))\n        return (\"stream\", gen)\n    r.setdefault(\"object\", \"chat.completion\")\n    return (\"obj\", r)\n\n\ndef _op_completion(model=None, prompt=None, stream=False, **kw):\n    r = yield (\"complete\", fa_llm.completions_to_chat(prompt, model=model, **{k: v for k, v in kw.items() if k in (\"temperature\", \"max_tokens\", \"top_p\", \"stop\", \"n\", \"seed\")}))\n    d = fa_llm.chat_to_completion(r)\n    d[\"model\"] = _model(r, model)\n    if stream:\n        def gen():\n            for c in d[\"choices\"]:\n                text = c[\"text\"]\n                for i in range(0, len(text), 24):\n                    yield {\"id\": d[\"id\"], \"object\": \"text_completion\", \"created\": d[\"created\"], \"model\": d[\"model\"], \"choices\": [{\"text\": text[i:i + 24], \"index\": c[\"index\"], \"finish_reason\": None}]}\n            yield {\"id\": d[\"id\"], \"object\": \"text_completion\", \"created\": d[\"created\"], \"model\": d[\"model\"], \"choices\": [{\"text\": \"\", \"index\": 0, \"finish_reason\": \"stop\"}]}\n        return (\"stream\", gen())\n    return (\"obj\", d)\n\n\ndef _op_response(model=None, input=None, instructions=None, stream=False, **kw):\n    r = yield (\"complete\", fa_llm.responses_to_chat(model=model, input=input, instructions=instructions, **kw))\n    d = fa_llm.chat_to_response(r, model)\n    if stream:\n        return (\"stream\", fa_llm.response_events(d))\n    return (\"obj\", d)\n\n\ndef _op_embeddings(input=None, model=None, dimensions=None, encoding_format=None, **kw):\n    body = {\"input\": input, \"model\": model or \"text-embedding-3-small\"}\n    if dimensions:\n        body[\"dimensions\"] = dimensions\n    if encoding_format:\n        body[\"encoding_format\"] = encoding_format\n    r = yield (\"upstream\", {\"cap\": \"embeddings\", \"path\": \"/embeddings\", \"json_body\": body})\n    return (\"obj\", (r or {}).get(\"json\") or {})\n\n\ndef _op_image(kind, **kw):\n    path = {\"generate\": \"/images/generations\", \"edit\": \"/images/edits\", \"variation\": \"/images/variations\"}[kind]\n    if kind == \"generate\":\n        body = {k: v for k, v in kw.items() if v is not None}\n        r = yield (\"upstream\", {\"cap\": \"images\", \"path\": path, \"json_body\": body})\n    else:\n        files, fields = [], {}\n        for k, v in kw.items():\n            if v is None:\n                continue\n            if k in (\"image\", \"mask\"):\n                for item in (v if isinstance(v, list) else [v]):\n                    files.append(fa_llm.file_part(\"image[]\" if isinstance(v, list) else k, item, k + \".png\", \"image/png\"))\n            else:\n                fields[k] = v\n        r = yield (\"upstream\", {\"cap\": \"images\", \"path\": path, \"form\": {\"fields\": fields, \"files\": files}})\n    return (\"obj\", (r or {}).get(\"json\") or {})\n\n\ndef _op_audio(kind, **kw):\n    if kind == \"speech\":\n        body = {k: v for k, v in kw.items() if v is not None}\n        r = yield (\"upstream\", {\"cap\": \"audio_speech\", \"path\": \"/audio/speech\", \"json_body\": body, \"want\": \"bytes\"})\n        import base64\n        return (\"bytes\", base64.b64decode((r or {}).get(\"b64\") or \"\"), (r or {}).get(\"content_type\"))\n    path = \"/audio/transcriptions\" if kind == \"transcriptions\" else \"/audio/translations\"\n    files = [fa_llm.file_part(\"file\", kw.pop(\"file\"), \"audio.wav\", \"audio/wav\")]\n    fields = {k: v for k, v in kw.items() if v is not None}\n    fmt = fields.get(\"response_format\")\n    r = yield (\"upstream\", {\"cap\": \"audio_transcribe\", \"path\": path, \"form\": {\"fields\": fields, \"files\": files}, \"want\": \"bytes\" if fmt in (\"text\", \"srt\", \"vtt\") else \"json\"})\n    if fmt in (\"text\", \"srt\", \"vtt\"):\n        import base64\n        return (\"text\", base64.b64decode((r or {}).get(\"b64\") or \"\").decode(\"utf-8\", \"replace\"))\n    return (\"obj\", (r or {}).get(\"json\") or {})\n\n\ndef _finish(res):\n    k = res[0]\n    if k == \"obj\":\n        return _Obj(res[1])\n    if k == \"stream\":\n        return res[1]\n    if k == \"bytes\":\n        return fa_sim.SimBytes(res[1], res[2])\n    return res[1]\n\n\ndef _run(gen):\n    res = _drive(gen)\n    return Stream(res[1]) if res[0] == \"stream\" else _finish(res)\n\n\nasync def _arun(gen):\n    res = await _adrive(gen)\n    return AsyncStream(res[1]) if res[0] == \"stream\" else _finish(res)\n\n\n# ---------------------------------------------------------------- 資源（同步與 async 兩套，內容一致）\ndef _make_resources(A):\n    \"\"\"A=True 產生 async 版。回傳 (client 屬性建立函式)。用 exec 風格太難讀，這裡用小工廠。\"\"\"\n    run = _arun if A else _run\n\n    def call(gen):\n        return run(gen)\n\n    class _Wrap(object):\n        def __init__(self, fn):\n            self._fn = fn\n\n        def __call__(self, *a, **kw):\n            return self._fn(*a, **kw)\n\n    def method(op):\n        if A:\n            async def m(self, *a, **kw):\n                return await run(op(*a, **kw))\n        else:\n            def m(self, *a, **kw):\n                return run(op(*a, **kw))\n        return m\n\n    def raw_method(op):\n        if A:\n            async def m(self, *a, **kw):\n                return _Raw(await run(op(*a, **kw)))\n        else:\n            def m(self, *a, **kw):\n                return _Raw(run(op(*a, **kw)))\n        return m\n\n    def simple(fn, wrap=True):\n        if A:\n            async def m(self, *a, **kw):\n                return _wrapx(fn(*a, **kw), wrap)\n        else:\n            def m(self, *a, **kw):\n                return _wrapx(fn(*a, **kw), wrap)\n        return m\n\n    def _wrapx(v, wrap):\n        return _Obj(v) if wrap and isinstance(v, dict) else v\n\n    class WithRaw(object):\n        def __init__(self, op):\n            self.create = raw_method(op).__get__(self)\n\n    class Completions(object):\n        create = method(_op_chat)\n\n        def __init__(self):\n            self.with_raw_response = WithRaw(_op_chat)\n            self.with_streaming_response = WithRaw(_op_chat)\n\n        def parse(self, *a, **kw):\n            fmt = kw.get(\"response_format\")\n            kw2 = dict(kw)\n            if fmt is not None and not isinstance(fmt, dict):\n                kw2[\"response_format\"] = {\"type\": \"json_object\"}\n            if A:\n                async def go():\n                    r = await self.create(*a, **kw2)\n                    return _parsed(r, fmt)\n                return go()\n            return _parsed(self.create(*a, **kw2), fmt)\n\n        def __getattr__(self, k):\n            raise NotSupportedError(\"chat.completions.%s 在 AI 助理的 openai 轉接版沒有支援\" % k)\n\n    def _parsed(r, fmt):\n        try:\n            text = r.choices[0].message.content\n            data = json.loads(text)\n            if fmt is not None and hasattr(fmt, \"model_validate\"):\n                data = fmt.model_validate(data)\n            r.choices[0].message.__dict__[\"_d\"][\"parsed\"] = data\n        except Exception:\n            pass\n        return r\n\n    class Chat(object):\n        def __init__(self):\n            self.completions = Completions()\n\n        def __getattr__(self, k):\n            raise NotSupportedError(\"chat.%s 在 AI 助理的 openai 轉接版沒有支援\" % k)\n\n    class LegacyCompletions(object):\n        create = method(_op_completion)\n\n    class Responses(object):\n        create = method(_op_response)\n\n        def __init__(self):\n            self.with_raw_response = WithRaw(_op_response)\n\n        def __getattr__(self, k):\n            raise NotSupportedError(\"responses.%s 在 AI 助理的 openai 轉接版沒有支援（只有 create）\" % k)\n\n    class Embeddings(object):\n        create = method(_op_embeddings)\n\n        def __init__(self):\n            self.with_raw_response = WithRaw(_op_embeddings)\n\n    class Images(object):\n        def generate(self, **kw):\n            return call(_op_image(\"generate\", **kw)) if not A else _arun(_op_image(\"generate\", **kw))\n\n        def edit(self, **kw):\n            return call(_op_image(\"edit\", **kw)) if not A else _arun(_op_image(\"edit\", **kw))\n\n        def create_variation(self, **kw):\n            return call(_op_image(\"variation\", **kw)) if not A else _arun(_op_image(\"variation\", **kw))\n\n    class _AudioSub(object):\n        def __init__(self, kind):\n            self.kind = kind\n            self.with_streaming_response = self\n\n        def create(self, **kw):\n            gen = _op_audio(self.kind, **kw)\n            return _arun(gen) if A else _run(gen)\n\n        def __enter__(self):\n            return self\n\n        def __exit__(self, *a):\n            return False\n\n    class Audio(object):\n        def __init__(self):\n            self.transcriptions = _AudioSub(\"transcriptions\")\n            self.translations = _AudioSub(\"translations\")\n            self.speech = _AudioSub(\"speech\")\n\n    class Models(object):\n        list = simple(lambda: fa_sim.models(_current_model())[0])\n        retrieve = simple(lambda model: fa_sim.models(model)[1])\n\n    class Moderations(object):\n        create = simple(lambda **kw: fa_sim.moderation(**kw))\n\n    class Files(object):\n        create = simple(lambda **kw: fa_sim.file_create(**kw))\n        retrieve = simple(lambda fid: fa_sim.file_get(fid)[0])\n        list = simple(lambda **kw: fa_sim.file_list())\n        delete = simple(lambda fid: fa_sim.file_delete(fid))\n        content = simple(lambda fid: fa_sim.SimBytes(fa_sim.file_get(fid)[1]), wrap=False)\n        retrieve_content = content\n\n    class Batches(object):\n        create = simple(lambda **kw: fa_sim.batch_create(**kw))\n        retrieve = simple(lambda bid: fa_sim.batch_get(bid))\n\n    class _Jobs(object):\n        create = simple(lambda **kw: fa_sim.finetune_create(**kw))\n        retrieve = simple(lambda jid: fa_sim._STORE[\"jobs\"][jid])\n\n    class FineTuning(object):\n        def __init__(self):\n            self.jobs = _Jobs()\n\n    class _Messages(object):\n        create = simple(lambda thread_id, **kw: fa_sim.message_create(thread_id, **kw))\n        list = simple(lambda thread_id, **kw: fa_sim.messages_list(thread_id, **kw))\n\n    class _Runs(object):\n        create = simple(lambda thread_id, **kw: fa_sim.run_create(thread_id, **kw))\n        create_and_poll = create\n        retrieve = simple(lambda thread_id, run_id: {\"id\": run_id, \"object\": \"thread.run\", \"status\": \"completed\"})\n\n    class _Threads(object):\n        create = simple(lambda **kw: fa_sim.thread_create(**kw))\n\n        def __init__(self):\n            self.messages = _Messages()\n            self.runs = _Runs()\n\n    class _Assistants(object):\n        create = simple(lambda **kw: fa_sim.assistant_create(**kw))\n\n    class _VectorStores(object):\n        create = simple(lambda **kw: fa_sim.vector_store_create(**kw))\n\n    class Beta(object):\n        def __init__(self):\n            self.chat = Chat()\n            self.threads = _Threads()\n            self.assistants = _Assistants()\n            self.vector_stores = _VectorStores()\n\n    return dict(Chat=Chat, Completions=LegacyCompletions, Responses=Responses, Embeddings=Embeddings, Images=Images, Audio=Audio, Models=Models,\n                Moderations=Moderations, Files=Files, Batches=Batches, FineTuning=FineTuning, Beta=Beta, VectorStores=_VectorStores)\n\n\n_CURRENT = {\"model\": None}\n\n\ndef _current_model():\n    if _CURRENT[\"model\"] is None:\n        try:\n            _CURRENT[\"model\"] = fa_bridge.call(\"llm.info\", {}, timeout=10.0).get(\"model\")\n        except Exception:\n            _CURRENT[\"model\"] = \"assistant\"\n    return _CURRENT[\"model\"]\n\n\ndef _client_class(A):\n    R = _make_resources(A)\n\n    class _Client(object):\n        def __init__(self, api_key=None, base_url=None, organization=None, project=None, timeout=None, max_retries=None, default_headers=None, http_client=None, **kw):\n            self.api_key = api_key\n            self.base_url = base_url\n            self.organization = organization\n            self.project = project\n            self.timeout = timeout\n            self.max_retries = max_retries\n            self.chat = R[\"Chat\"]()\n            self.completions = R[\"Completions\"]()\n            self.responses = R[\"Responses\"]()\n            self.embeddings = R[\"Embeddings\"]()\n            self.images = R[\"Images\"]()\n            self.audio = R[\"Audio\"]()\n            self.models = R[\"Models\"]()\n            self.moderations = R[\"Moderations\"]()\n            self.files = R[\"Files\"]()\n            self.batches = R[\"Batches\"]()\n            self.fine_tuning = R[\"FineTuning\"]()\n            self.beta = R[\"Beta\"]()\n            self.vector_stores = R[\"VectorStores\"]()\n            self.with_raw_response = self\n            self.with_streaming_response = self\n\n        def with_options(self, **kw):\n            return self\n\n        copy = with_options\n\n        def close(self):\n            return None\n\n        def __enter__(self):\n            return self\n\n        def __exit__(self, *a):\n            return False\n\n        def __getattr__(self, k):\n            if k.startswith(\"__\"):\n                raise AttributeError(k)\n            raise NotSupportedError(\"client.%s 在 AI 助理的 openai 轉接版沒有支援\" % k)\n\n    return _Client\n\n\nclass OpenAI(_client_class(False)):\n    pass\n\n\nclass AsyncOpenAI(_client_class(True)):\n    async def close(self):\n        return None\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *a):\n        return False\n\n\nAzureOpenAI = OpenAI\nAsyncAzureOpenAI = AsyncOpenAI\n\n# 舊版（0.x）的模組層級寫法：openai.ChatCompletion.create(...)、openai.Embedding.create(...)\n_default = OpenAI()\nchat = _default.chat\ncompletions = _default.completions\nresponses = _default.responses\nembeddings = _default.embeddings\nimages = _default.images\naudio = _default.audio\nmodels = _default.models\nmoderations = _default.moderations\nfiles = _default.files\napi_key = None\nbase_url = None\n\n\nclass ChatCompletion(object):\n    @staticmethod\n    def create(*a, **kw):\n        return _default.chat.completions.create(*a, **kw)\n\n\nclass Embedding(object):\n    @staticmethod\n    def create(*a, **kw):\n        return _default.embeddings.create(*a, **kw)\n\n\nclass Completion(object):\n    @staticmethod\n    def create(*a, **kw):\n        return _default.completions.create(*a, **kw)\n","playwright/__init__.py":"# -*- coding: utf-8 -*-\n\"\"\"Floating AI Assistant 的 playwright 轉接版（見 sync_api.py）。\"\"\"\n","playwright/sync_api.py":"# -*- coding: utf-8 -*-\n\"\"\"\nplaywright.sync_api 的「轉接版」：Floating AI Assistant 在執行技能包的 Python 腳本時提供。\n\n腳本照原本的寫法用 Playwright（connect_over_cdp／launch、new_page、goto、inner_text、locator、screenshot…），\n但這裡的每個動作實際上都是呼叫 AI 助理自己的瀏覽器控制工具（Chrome 擴充功能開的「AI Controlled」分頁），\n不需要 Chrome 遠端除錯埠、也不用安裝 Playwright。使用者的登入狀態就是他自己 Chrome 的登入狀態。\n\n支援的子集合：sync_playwright().start()/stop()/with、chromium|firefox|webkit .connect_over_cdp()/.launch()、\nbrowser.contexts/new_context/new_page/close、context.pages/new_page/close、\npage.goto/url/title/content/inner_text/text_content/evaluate/screenshot/wait_for_timeout/wait_for_load_state/\nwait_for_selector/locator/close、locator.first/count/inner_text/text_content/screenshot/click。\n其他功能會丟出說明清楚的 NotImplementedError——請改用 fa_bridge.tool(...) 或 fa_bridge.domain(...)。\n\"\"\"\nimport sys\nimport time\n\nimport fa_bridge\n\n_NOTED = [False]\n\n\ndef _note():\n    if not _NOTED[0]:\n        _NOTED[0] = True\n        sys.stderr.write(\"[fa-bridge] playwright is routed to the AI assistant browser tools (no Chrome debug port needed)\\n\")\n\n\ndef _nyi(what):\n    raise NotImplementedError(\n        \"%s 在 AI 助理的 playwright 轉接版沒有支援。可以改用 fa_bridge.tool('browser_…', …) 呼叫助理的瀏覽器工具，\"\n        \"或 fa_bridge.domain('browser_control', '要做的事') 委派給瀏覽器控制領域。\" % what)\n\n\nclass Locator(object):\n    def __init__(self, page, selector, index=0):\n        self._page = page\n        self._sel = selector\n        self._idx = index\n\n    @property\n    def first(self):\n        return Locator(self._page, self._sel, 0)\n\n    @property\n    def last(self):\n        return Locator(self._page, self._sel, -1)\n\n    def nth(self, i):\n        return Locator(self._page, self._sel, i)\n\n    def locator(self, sub):\n        return Locator(self._page, self._sel + \" \" + sub, 0)\n\n    def count(self):\n        return int(fa_bridge.call(\"pw.count\", {\"tab\": self._page._tab, \"selector\": self._sel}) or 0)\n\n    def inner_text(self, **kw):\n        return fa_bridge.call(\"pw.text\", {\"tab\": self._page._tab, \"selector\": self._sel, \"index\": self._idx}) or \"\"\n\n    text_content = inner_text\n\n    def screenshot(self, path=None, **kw):\n        return self._page._shot(path, False, self._sel, self._idx)\n\n    def click(self, **kw):\n        fa_bridge.call(\"pw.click\", {\"tab\": self._page._tab, \"selector\": self._sel, \"index\": self._idx})\n\n    def is_visible(self, **kw):\n        return self.count() > 0\n\n    def __getattr__(self, name):\n        _nyi(\"locator.\" + name)\n\n\nclass Page(object):\n    def __init__(self, tab=None):\n        self._tab = tab\n        self._url = \"\"\n        self.closed = False\n\n    @property\n    def url(self):\n        try:\n            self._url = fa_bridge.call(\"pw.url\", {\"tab\": self._tab}) or self._url\n        except fa_bridge.BridgeError:\n            pass\n        return self._url\n\n    def goto(self, url, wait_until=None, timeout=None, **kw):\n        r = fa_bridge.call(\"pw.goto\", {\"tab\": self._tab, \"url\": url})\n        if isinstance(r, dict) and r.get(\"tab\"):\n            self._tab = r[\"tab\"]\n        self._url = url\n        return None\n\n    def title(self):\n        return fa_bridge.call(\"pw.eval\", {\"tab\": self._tab, \"js\": \"document.title\"}) or \"\"\n\n    def content(self):\n        return fa_bridge.call(\"pw.eval\", {\"tab\": self._tab, \"js\": \"document.documentElement.outerHTML\"}) or \"\"\n\n    def inner_text(self, selector=\"body\", **kw):\n        return fa_bridge.call(\"pw.text\", {\"tab\": self._tab, \"selector\": selector}) or \"\"\n\n    text_content = inner_text\n\n    def evaluate(self, expression, arg=None):\n        js = expression\n        e = expression.lstrip()\n        is_fn = e.startswith((\"function\", \"async function\")) or (\"=>\" in e and e.startswith((\"(\", \"async\", \"_\", \"x\", \"e\", \"el\")) and not e.endswith(\")\"))\n        if arg is not None:\n            import json\n            js = \"(\" + expression + \")(\" + json.dumps(arg) + \")\"\n        elif is_fn:\n            js = \"(\" + expression + \")()\"\n        return fa_bridge.call(\"pw.eval\", {\"tab\": self._tab, \"js\": js})\n\n    def locator(self, selector, **kw):\n        return Locator(self, selector)\n\n    def query_selector(self, selector):\n        loc = Locator(self, selector)\n        return loc if loc.count() > 0 else None\n\n    def wait_for_timeout(self, ms):\n        fa_bridge.sleep(float(ms) / 1000.0)\n\n    def wait_for_load_state(self, *a, **kw):\n        fa_bridge.sleep(0.3)\n\n    def wait_for_selector(self, selector, timeout=30000, **kw):\n        t0 = time.time()\n        loc = Locator(self, selector)\n        while time.time() - t0 < timeout / 1000.0:\n            if loc.count() > 0:\n                return loc\n            fa_bridge.sleep(0.4)\n        raise TimeoutError(\"等不到元素：\" + selector)\n\n    def set_viewport_size(self, *a, **kw):\n        pass\n\n    def bring_to_front(self):\n        pass\n\n    def screenshot(self, path=None, full_page=False, **kw):\n        return self._shot(path, full_page, None, 0)\n\n    def _shot(self, path, full_page, selector, index):\n        if path:\n            import os\n            path = os.path.abspath(path)\n            d = os.path.dirname(path)\n            if d and not os.path.isdir(d):\n                os.makedirs(d)\n        r = fa_bridge.call(\"pw.screenshot\", {\"tab\": self._tab, \"full_page\": bool(full_page), \"selector\": selector, \"index\": index})\n        if not (isinstance(r, dict) and r.get(\"base64\")):\n            raise RuntimeError(\"截圖失敗\")\n        import base64\n        data = base64.b64decode(r[\"base64\"])\n        if path:\n            with open(path, \"wb\") as f:\n                f.write(data)\n            return None\n        return data\n\n    def close(self, **kw):\n        if not self.closed:\n            self.closed = True\n            try:\n                fa_bridge.call(\"pw.close\", {\"tab\": self._tab})\n            except fa_bridge.BridgeError:\n                pass\n\n    def __getattr__(self, name):\n        _nyi(\"page.\" + name)\n\n\nclass Context(object):\n    def __init__(self, browser):\n        self._browser = browser\n        self.pages = []\n\n    def new_page(self):\n        p = Page(None)\n        r = fa_bridge.call(\"pw.new_page\", {})\n        p._tab = r.get(\"tab\") if isinstance(r, dict) else None\n        self.pages.append(p)\n        return p\n\n    def close(self):\n        for p in list(self.pages):\n            p.close()\n\n    def __getattr__(self, name):\n        _nyi(\"context.\" + name)\n\n\nclass Browser(object):\n    def __init__(self):\n        self.contexts = [Context(self)]\n\n    def new_context(self, **kw):\n        c = Context(self)\n        self.contexts.append(c)\n        return c\n\n    def new_page(self, **kw):\n        return self.contexts[0].new_page()\n\n    def close(self):\n        for c in self.contexts:\n            c.close()\n\n    def is_connected(self):\n        return True\n\n    def __getattr__(self, name):\n        _nyi(\"browser.\" + name)\n\n\nclass BrowserType(object):\n    def connect_over_cdp(self, endpoint_url=None, **kw):\n        _note()\n        fa_bridge.call(\"pw.status\", {})\n        return Browser()\n\n    connect = connect_over_cdp\n\n    def launch(self, **kw):\n        _note()\n        fa_bridge.call(\"pw.status\", {})\n        return Browser()\n\n    def launch_persistent_context(self, user_data_dir=None, **kw):\n        return self.launch().contexts[0]\n\n\nclass Playwright(object):\n    def __init__(self):\n        self.chromium = BrowserType()\n        self.firefox = BrowserType()\n        self.webkit = BrowserType()\n\n    def stop(self):\n        pass\n\n\nclass _Manager(object):\n    def start(self):\n        return Playwright()\n\n    def __enter__(self):\n        return Playwright()\n\n    def __exit__(self, *a):\n        return False\n\n\ndef sync_playwright():\n    return _Manager()\n\n\n# 常見的型別名稱，讓 `from playwright.sync_api import Page, Browser, TimeoutError` 不會出錯\nTimeoutError = TimeoutError\nError = RuntimeError\n"};
/* PYBRIDGE-END */
