                if (d.chosen) lines.push(`選中：${d.chosen.domain} / ${d.chosen.pattern}（${d.chosen.via}，分數 ${d.chosen.score}）→ ${d.chosen.tool ? '工具 ' + d.chosen.tool + ' ' + JSON.stringify(d.chosen.args) : (d.chosen.slash ? '指令 ' + d.chosen.slash : '回答')}`);
