                        if (!opts.overwrite) { conflicts.push(`知識 ${e.kind}:${e.key}：你已經有不同的版本，保留你的（要覆蓋請帶 overwrite）`); kr.kept_yours++; continue; }
                        ku.typed.splice(i, 1);
