            const fence = String.fromCharCode(96, 96, 96);
            say((r.warning ? '⚠️ ' + r.warning + '\n\n' : '') + r.answer + (r.snippets && r.snippets.length ? '\n\n' + r.snippets.map((x) => x.path + ':' + x.from_line + '\n' + fence + '\n' + x.text + '\n' + fence).join('\n') : ''));
