            const fmt = /^qa/.test(rest) ? 'qa_html' : 'sqlite_html';
            try { const r = await this._codeExport(root, fmt, { deliver: true }); say('📦 已匯出 ' + r.filename + '（' + Math.round(r.bytes / 1048576 * 10) / 10 + ' MB）。'); } catch (e) { say('⚠️ 匯出失敗：' + String((e && e.message) || e)); }
