        const srv = { closed: false, conns };
        srv.push = (obj) => { const s = JSON.stringify(obj); conns.forEach((reply, id) => { try { reply({ t: 'ws_msg', id, data: s }); } catch (_) {} }); };
        const QA_PROTOCOL = '你是專案索引檢視器裡的助理，使用者在檢視器裡問這個專案的問題。\n做法：先用 repo_ask 取得索引的事實（定義在哪、誰用到、相關檔案），需要確認時用 coding_read_file 等讀程式碼，不要整個專案亂讀。\n回答用繁體中文白話，具體、有依據；引用檔案請用反引號包路徑（例如 src/a.js），定義用反引號包名稱，檢視器會把它們變成可點的連結。不要編造索引裡沒有的內容，不確定就說不確定。\n如果你讀過程式碼、確認了某個檔案或定義在做什麼，順手用 repo_map({"action":"annotate","root":"<專案>","path":"<檔案>","note":"用途一句話，必要時接著用清單或表格整理重點（Markdown，2000字內）","symbols":{"名稱":"做什麼（可多行、可用表格）"}}) 補進資料庫（只寫確認過的）。\n最後只輸出要給使用者看的回答。';
        const TOOLS = /^(repo_map|repo_ask|repo_read_doc|coding_read_file|fap_read_file|fap_list_files|fap_find_file|fs_read_file|fs_list_files|list_file_access_points)$/;
        const notesVer = async () => ((await me._repoMapLoad(key)) || {}).notes_ver || 0;
        const jobsObj = () => {
            const ij = me._repoIndexStatus(key), dj = me._diveJob && me._diveJob.root === key ? me._diveJob : null;
            return { index: ij ? { running: !!ij.running, percent: ij.percent || 0 } : null, dive: dj ? { running: dj.state === 'running', done: dj.done + dj.failed, total: dj.total } : null };
        };
