        const lines = []; for (const x of r.results) { if (x.kind === 'error') lines.push(...x.matches.slice(0, 6).map((m) => '- **' + m.name + '**（' + m.system + ' ' + (m.hex || m.code) + '）：' + (m.note || m.message))); else if (x.kind === 'pragma') lines.push('- \x60#pragma ' + x.pragma.pragma + '\x60：' + x.pragma.desc + x.pragma.clauses.map((c) => '\n  - ' + c.clause + '：' + c.desc).join('')); else if (x.kind === 'command_line') lines.push(x.markdown); else if (x.kind === 'command') lines.push('- **' + x.command.program + '**：' + x.command.summary + '（' + x.command.options.length + ' 個選項）'); else if (x.kind === 'option') lines.push('- ' + x.command + ' \x60' + x.flag + (x.arg ? ' ' + x.arg : '') + '\x60：' + x.desc); else lines.push('- [' + x.kind + '] **' + x.key + '**：' + x.text); }
