        const act = String(p.action || '').toLowerCase();
        const u = this._behUserDefs();
        const lang = String(p.lang || p.language || 'c').toLowerCase();
        if (act === 'list') {
            const base = FA_BEHAVIOR_DATA;
            return { ok: true, builtin: { categories: Object.keys(base.patterns.categories).length, api_functions: Object.fromEntries(Object.entries(base.api).map(([k, v]) => [k, Object.keys(v).length])), idioms: Object.fromEntries(Object.entries(base.patterns.assembly_idioms || {}).map(([k, v]) => [k, v.length])) }, user: { categories: Object.keys(u.categories).length, api: Object.fromEntries(Object.entries(u.api).map(([k, v]) => [k, Object.keys(v).length])), idioms: Object.fromEntries(Object.entries(u.idioms).map(([k, v]) => [k, v.length])), notes: Object.fromEntries(Object.entries(u.notes).map(([k, v]) => [k, Object.keys(v).length])) } };
        }
        if (act === 'export') return { ok: true, format: 'fa-behavior-defs', version: 1, defs: u };
