            const remDirs = this._repoMapUnlisted(map).length, remFiles = this._repoMapFrontierFiles(map).length;
            map.index_built = (remDirs === 0 && remFiles === 0) || !!job.capped;
            map.stage = 'index';
            if (!remFiles) map.reanalyze = false;
