        const ttsCacheClearBtn = document.getElementById('ai-tts-model-cache-clear');
        if (ttsCacheClearBtn) {
            ttsCacheClearBtn.addEventListener('click', async () => {
                if (!confirm('清除已下載的語音合成模型快取？下次語音合成會重新下載約 90MB（已安裝的語音包不受影響）。')) return;
                const ok = await this._clearTtsModelCache();
                this._log(ok ? '🗑️ 已清除語音合成模型快取' : '⚠️ 清除模型快取失敗');
                this._refreshTtsCacheSizeDisplay();
            });
        }
        const ttsPreviewBtn = document.getElementById('ai-tts-preview-btn');
        if (ttsPreviewBtn) {
            ttsPreviewBtn.addEventListener('click', () => this._previewTtsVoice(false, ttsPreviewBtn, 'ai-tts-preview-player-slot'));
        }
        const ttsApiPreviewBtn = document.getElementById('ai-tts-api-preview-btn');
        if (ttsApiPreviewBtn) {
            ttsApiPreviewBtn.addEventListener('click', () => this._previewTtsVoice(true, ttsApiPreviewBtn, 'ai-tts-api-preview-player-slot'));
        }
        const ttsDefaultSpeedSlider = document.getElementById('ai-tts-default-speed');
        const ttsDefaultSpeedLabel = document.getElementById('ai-tts-default-speed-label');
        if (ttsDefaultSpeedSlider) {
            ttsDefaultSpeedSlider.addEventListener('input', () => {
                if (ttsDefaultSpeedLabel) ttsDefaultSpeedLabel.textContent = Number(ttsDefaultSpeedSlider.value).toFixed(2) + 'x';
            });
            ttsDefaultSpeedSlider.addEventListener('change', () => {
                const n = Number(ttsDefaultSpeedSlider.value);
                this.advancedSettings.ttsDefaultSpeed = Number.isFinite(n) && n >= 0.5 && n <= 2.0 ? n : 1.0;
                this._saveAdvancedSettings();
            });
        }
        const ttsVoiceListEl = document.getElementById('ai-tts-voice-list');
        if (ttsVoiceListEl) {
            ttsVoiceListEl.addEventListener('click', async (e) => {
                const btn = e.target.closest('[data-tts-delete-voice]');
                if (!btn) return;
                const voiceId = btn.dataset.ttsDeleteVoice;
                if (!confirm(`刪除已安裝的語音包「${voiceId}」？之後要再用到會重新下載。`)) return;
                await this._deleteTtsVoice(voiceId);
                this._renderTtsVoicePanel();
            });
        }
        [functionsInput, toolScriptInput, fnCodeInput].forEach(textarea => {
            textarea.addEventListener('scroll', () => this._syncCodeEditor(textarea.closest('.ai-code-editor')));
            textarea.addEventListener('input', () => this._syncCodeEditor(textarea.closest('.ai-code-editor')));
        });
        document.getElementById('ai-tool-editor-save').onclick = () => {
            const name = toolNameInput.value.trim();
            if (!name) {
                alert('Tool 名稱不能為空。');
                return;
            }
            if (this._isToolNameDuplicate(name, this.activeToolEditIndex)) {
                alert("Tool 名稱已存在：" + name);
                return;
            }
            try {
                this._validateCustomScript(functionsInput.value, 'Customize Functions');
                this._validateCustomScript(toolScriptInput.value, "Tool " + name + " Handler Script");
            } catch (err) {
                alert(err.message);
                return;
            }
            const bundleSelect = document.getElementById('ai-tool-skill-bundle-select');
            // tw_stock_db客製: 防禦性寫法——正常流程下change handler會在建立
            // 新技能包後立刻把選單值換成真正的id，'__create_new__'這個字面
            // 值理論上不會存到這裡；萬一使用者用prompt()取消建立卻選單值
            // 沒被reset就直接按儲存，這裡當成未分類，不要把這個無意義的字串
            // 存成skillBundleId（會讓工具在任何domain底下都篩選不到，悄悄
            // 消失叫不到）。
            const bundleIdValue = bundleSelect && bundleSelect.value !== '__create_new__' ? bundleSelect.value : '';
            const nextTool = this._normalizeCustomTool({
                name,
                description: toolDescInput.value,
                handlerScript: toolScriptInput.value,
                skillBundleId: bundleIdValue,
            }, name);
            if (this.activeToolEditIndex >= 0) {
                this.advancedSettings.customTools.splice(this.activeToolEditIndex, 1, nextTool);
            } else {
                this.advancedSettings.customTools.push(nextTool);
            }
            this._syncSkillBundleDomains();
            this._saveAdvancedSettings();
            this._renderCustomToolList();
            this._renderSkillBundleList();
            this._closeToolEditor();
            this._log("已儲存自訂工具: " + name);
        };
        document.getElementById('ai-fn-editor-save').onclick = () => {
            const fnNameInput = document.getElementById('ai-fn-name-input');
            const fnDescInput = document.getElementById('ai-fn-desc-input');
            const name = fnNameInput.value.trim();
            const originalName = fnNameInput.dataset.originalName || '';
            const desc = fnDescInput.value.trim();
            const code = fnCodeInput.value.trim();
            if (!name) {
                alert('函式名稱不能為空。');
                return;
            }
            if (!code) {
                alert('函式體不能為空。');
                return;
            }
            try {
                this._validateCustomScript(code, 'AI函式 "' + name + '"');
            } catch (err) {
                alert(err.message);
                return;
            }
            if (!this.advancedSettings.aiCustomFunctions) this.advancedSettings.aiCustomFunctions = {};
            if (originalName && originalName !== name && Object.prototype.hasOwnProperty.call(this.advancedSettings.aiCustomFunctions, originalName)) {
                delete this.advancedSettings.aiCustomFunctions[originalName];
            }
            this.advancedSettings.aiCustomFunctions[name] = { description: desc, code };
            this._saveAdvancedSettings();
            this._syncFromAI();
            this._renderAiFnList();
            this._closeAiFnEditor();
            this._log("已儲存AI函式: " + name);
        };
        if (advancedModal) {
            advancedModal.addEventListener('click', (event) => {
                if (event.target === advancedModal) this._closeAdvancedModal();
            });
        }
